/* Kids' books: 3-letter-or-shorter parodies, generated by tools/build-kids-readers.mjs from library/kid-stories. Do not edit. */
window.READERS.push(
  { id: "k-209-the-moon-mop", title: "The moon mop", pay: 936, kid: true, text: "Pip won a run to a tan orb. \"I own it all!\" His fur put mud on it. Fay put a mop in his paw. Pip had to mop his mud up. He was an orb guy who had to mop all day." },
  { id: "k-181-the-charade-nap", title: "The charade nap", pay: 1080, kid: true, text: "Kit had to act a log. She lay on the sod. Fay had to say it. \"A bed?\" Kit did not nod. \"A rug?\" Kit did not nod. She did ask Kit to get up. Kit had a nap. Fay put a rug on her. \"A nap?\" Fay won the cup." },
  { id: "k-107-the-soup-test", title: "The soup test", pay: 1080, kid: true, text: "Gus had a pot of pea tea. Fay had to say the mix to win a fig. She had a sip. She did not see it. A pea got off the fur of Gus. Fay saw it. She did say pea and won. Gus hid his fur in a hat." },
  { id: "k-207-the-big-roar", title: "The big roar", pay: 1080, kid: true, text: "Ned hid in a den. \"I am bad!\" Fay ran in, a bag on her arm. Ned let out a big cry. Fay put a nut in his paw. \"Do it a lot.\" Ned did. A fig hit the mud. Fay got it. Ned got pay to cry at a fig all day." },
  { id: "k-063-the-gem-tea", title: "The Gem Tea", pay: 1104, kid: true, text: "Gus had a gem but no pie. He put it in a pot of hot tea. Ned put a fig in it. Dot put an egg in it. Bo put an oat in it. All ate. No one ate the gem. \"My gem got me tea!\" Gus did say." },
  { id: "k-210-the-nut-shield", title: "The nut shield", pay: 1104, kid: true, text: "Kit has a nut mat to bar a foe. Bo let a pea hit it. No pea got by. Bo saw a nut to eat. Kit let him eat it. Dot ate one too. The mat had a gap now. Bo let a pea fly at Kit. She ate it to win." },
  { id: "k-208-the-code-cup", title: "The code cup", pay: 1104, kid: true, text: "Max met Gus at a tea hut. \"The red hen has a tan hat,\" Max did say. Gus got him a red cup and a tan lid. \"I ask for the key!\" Max did cry. Gus put a key in the cup. Max got it. He had to pay for tea too." },
  { id: "k-211-the-red-clue", title: "The red clue", pay: 1128, kid: true, text: "Dot had a red rag she did not see. Gus had a map to aid her. He saw a red dot on a pot. \"A cue!\" But his pen had no cap. It put the dot on the pot. Dot got her rag off his map. Gus put on the pen cap." },
  { id: "k-033-the-box-map", title: "The Box Map", pay: 1128, kid: true, text: "Max let Pip use his map to a gem. Pip dug by an oak. He dug by a hut. Max sat on a box to see. Pip did ask how to get in it. Max got up. It had a nut. Pip got the nut. Max put an X on his box." },
  { id: "k-098-the-royal-sun", title: "The Royal Sun", pay: 1128, kid: true, text: "Max had no sun in his den. He did ask Dot for one. Dot got Ned, his son. \"A son for you!\" Ned was not hot. Max put sun on a tag in ink. Dot lit a wax rod. Now Max had a sun in a tin. Ned had tea for two." },
  { id: "k-061-the-pie-cottage", title: "The Pie Cottage", pay: 1128, kid: true, text: "Pip was as big as a pea. Dot set a big pie by him. Pip ate a bit. He did not eat it all. He ate a gap for his den. Dot put a cup by it. \"Now tea is by the den.\" Pip sat on a pea. \"I may eat my bed too.\"" },
  { id: "k-280-the-hero-pose", title: "The hero pose", pay: 1128, kid: true, text: "Pip was up on a log. Kit ran to aid him. \"I am the top guy!\" Pip did ask for a web. Kit put one paw on her hip. \"I am so big!\" Pip got on her hat. Kit hit hay. Pip got out. \"You did aid me,\" he did say." },
  { id: "k-224-the-sock-comet", title: "The sock comet", pay: 1128, kid: true, text: "Dot saw a red dot by her toy sun. Max put his eye to a gem. \"A hot orb!\" Dot hit a pot. Max put a net in its way. It got a rag. Bo ran up to get it. He had let it fly at a peg. His big orb was but a rag." },
  { id: "k-203-the-lost-fig", title: "The lost fig", pay: 1152, kid: true, text: "Gus had to get a fig. Ned saw jam on a rug. Gus got a gem to see a big dot of jam. Jam was on a cup too! Ned saw jam on the gem. Gus had cut his fig on it. The fig was in his hat. His job got him a fig." },
  { id: "k-219-the-wax-clue", title: "The wax clue", pay: 1152, kid: true, text: "Gus had a hat he did not see. A wax toy sat on a box. Gus did ask it for aid. It did not say a bit. Gus sat by it all day. The sun got hot. The toy did bow. His hat got off it. Gus did bow to it too." },
  { id: "k-262-the-flat-maze", title: "The flat maze", pay: 1152, kid: true, text: "Ned put a key in a web of hay. Fay had to get it. She ran by a gap and hit a bad end. Ned did nod. Fay put her paw by the hay and got it up. The key was on a mat. \"I won!\" Ned had to get his web up now." },
  { id: "k-031-the-lost-pin", title: "The Lost Pin", pay: 1176, kid: true, text: "Ned had no gem on his hat. Gus dug by a log. No gem. He dug by a box. No gem. Now he got tea. The gem was in his cup. It was a pin. Ned put it on his hat. Gus got the cup. It was a gem too, to his eye." },
  { id: "k-029-the-rod-shop", title: "The Rod Shop", pay: 1176, kid: true, text: "Kit got a rod off Bo. She hit a cup. The cup did not do a jig. A dog ran in and got the rod. Bo let it go. Kit got a cup of jam. She put a pea in it. It was a gem now. She ate it. The dog had a rod. Kit had jam." },
  { id: "k-268-the-soft-landing", title: "The soft landing", pay: 1176, kid: true, text: "Pip put his toy jet on a bed. Bo got in. Pip hit the bed. The jet got up and hit a cot. Bo got out. \"I got to a new orb!\" Pip did hop on the cot too. The new orb was fun, but Bo had to set his bed for a nap." },
  { id: "k-218-the-echo-foe", title: "The echo foe", pay: 1176, kid: true, text: "Bo had a rod in a den on a red orb. \"Who is in the den?\" he did cry. \"Den!\" Bo bid the foe go. The foe bid him go too. Ned put a rug up in the den. No foe! Bo put a nut on the rug as pay for its big act." },
  { id: "k-053-the-silent-court", title: "The Silent Court", pay: 1176, kid: true, text: "Max had a new law. No din in his den. Dot sat and did not hum. Max ate a fig. \"Hic!\" Dot put a lid on his cup. Max got a sip. \"Hic!\" Max cut his law up. Dot did hum. Max hit his cup on a pan. Now hic was in the gig." },
  { id: "k-037-the-bog-gem", title: "The Bog Gem", pay: 1176, kid: true, text: "Dot saw a gem in a bog. She did ask it for a bun. Pip did ask for jam. Gus had a jug of oil. Its ray was the gem. Gus had a bun and jam too. He let Dot and Pip eat. Dot put a nut by the jug. Now her gem got a tip." },
  { id: "k-202-the-hat-peg", title: "The hat peg", pay: 1176, kid: true, text: "Kit had a red hat. Dot was too hot. Kit ran to aid her. \"I can fly!\" The hat got on a peg. Kit had to sit on a box to get it off. Dot sat by Kit, out of the sun. \"You did aid me,\" Dot did say. Kit sat all day." },
  { id: "k-217-the-web-bed", title: "The web bed", pay: 1176, kid: true, text: "Max was up in an oak. Kit set a web to get him out. Max got in it and lay low. Kit did tug. Max did not get up. \"Are you ill?\" \"No. It is a bed.\" Kit got in too. By six the two had a nap. No one got out." },
  { id: "k-154-the-wet-score-pad", title: "The wet score pad", pay: 1176, kid: true, text: "Max put a dot on a pad for a hit in the net. Ned had to win. Max got the pad wet by his cup of tea. Ned saw all the ink was off. \"I can win now!\" he did say. Max put one dot on a nut. Ned ate it. \"I win now too.\"" },
  { id: "k-213-the-jet-pot", title: "The jet pot", pay: 1200, kid: true, text: "Bo has a jet of tin. It has no din. Max has to get it by Gus. Bo put a pot in it. \"Hit it to get aid.\" The jet hit a log. The pot hit Max. Gus got up. Bo put a rag in the pot. Now the jet can get by Gus." },
  { id: "k-254-the-nut-case", title: "The nut case", pay: 1200, kid: true, text: "Dot had a nut in a box. Now it was not in the box. Gus saw a dip in the lid. He put his paw to it. The nut hit his paw. It was in a gap in the lid! Dot had put the lid on it. She put her nut in a bag now." },
  { id: "k-281-the-sum-bot", title: "The sum bot", pay: 1200, kid: true, text: "Max has a sum bot. Dot put a nut and a nut by it. \"One and one?\" The bot did not say two. It ate a nut. Dot did ask a lot. It ate the new nut. Max had to get the nut jar. The bot had a sum now. \"No nut!\" Dot had to nod." },
  { id: "k-215-the-pea-jet", title: "The pea jet", pay: 1200, kid: true, text: "Dot set a pea jet on a pan. Kit was the top guy. \"To the far rim!\" Dot hit the pan. The pea hit a cup. Kit had to get it out. It was too far in. Dot put hot tea in it. Kit ate the pea. The big run was to tea." },
  { id: "k-227-the-spy-pie", title: "The spy pie", pay: 1200, kid: true, text: "Fay put a spy tag in a pie. Ned was to see it at six. He ate it at ten to six. Fay ran in to get his spy tag. Ned had no tag. Fay got him a new pie, a tag on top. It bid him get a pie. He had a pie all day." },
  { id: "k-111-the-lost-gold", title: "The lost gold", pay: 1200, kid: true, text: "Kit had a map to a gem. Gus had to dig by an oak. He dug a big pit. Kit saw a box in it. Gus got the box. It had a gem and a map. Gus saw the new map. It led to the oak too. \"No,\" he did say. \"One pit is my lot.\"" },
  { id: "k-234-the-tea-jet", title: "The tea jet", pay: 1200, kid: true, text: "Bo has a nut on a web in his toy jet. \"All can fly up in air!\" Gus cut the web. The nut hit Bo. Gus put a bag of tea on the jet. It got cut. Bo had tea in his fur too. His jet was for tea, not for the sky." },
  { id: "k-250-the-tiny-gate", title: "The tiny gate", pay: 1200, kid: true, text: "Dot has a gap in a rim. Fay put a pea in it. The pea got on a pan by her. \"A new orb!\" Dot did cry. Fay put her paw in. It got by the pea. Dot put a fig in it. At six the two had tea but did not get off the mat." },
  { id: "k-135-the-best-guess", title: "The best guess", pay: 1200, kid: true, text: "Fay had a nut jar. Max had to say how big the nut sum was. Fay let him get it. Max ate a nut. He ate two. He did add as he ate. Max got it all and won the jar. Fay put one nut in it. \"Try now,\" she did say." },
  { id: "k-230-the-boss-seat", title: "The boss seat", pay: 1200, kid: true, text: "Ned sat on a tan cot at the top of a log. Dot had to bow to him. Her lip hit a cot leg. The cot did sag. Ned and his cot hit the mud. It was fun! Dot put him on the log for a nut. The guy had to pay to sit." },
  { id: "k-248-the-lost-sun", title: "The lost sun", pay: 1200, kid: true, text: "Gus saw the sun go dim in his gem. Bo hit a pot. All ran up. Gus saw a big orb in the sky. Kit got a hat off the gem. Bo had put it on to bar mud. The sun was out. Bo had to hit the pot to end the din." },
  { id: "k-240-the-lid-ray", title: "The lid ray", pay: 1200, kid: true, text: "Max has a ray to get up a lid. Gus did use it on an ink jar. The ink hit his fur. Gus did use it on a tin box. The lid hit a pot. Dot ran up for tea. Max sat on a mat of ink. Dot put a cup by him. \"Is it tea?\"" },
  { id: "k-057-the-late-spell", title: "The Late Spell", pay: 1224, kid: true, text: "At ten, Kit had to do a hex. Gus got her a tag to use. Kit did say the hex. Gus had a nap. Kit had a nap too. At six, Kit got up. Gus got up too. Kit put the tag by a bed. The hex was not for her try. It was for a nap." },
  { id: "k-092-the-air-market", title: "The Air Market", pay: 1224, kid: true, text: "Max had a jar of air. It had a tag: New air. Dot did pay a nut for it. Max got the lid up. Dot did not see her air. She put a new nut in a jar. \"Nut air for you!\" Max did pay a gem. Dot got her nut out. Max saw no nut air." },
  { id: "k-295-the-web-jet", title: "The web jet", pay: 1224, kid: true, text: "Bo had a toy jet. Pip put it on a web. Bo got in. The jet got as far as a log. \"Why am I by the log?\" Pip had the web in his paw. He let it go. The jet got by the log. Bo was off. Pip had to run to get it." },
  { id: "k-220-the-new-paw", title: "The new paw", pay: 1224, kid: true, text: "Max got Dot a tin paw. It can use a cup and a key. Dot got Pip in a hug. The tin paw did not let go. Max hit a red dot on it. It let Pip go and got Max. Dot sat. Her pal had to aid her. The paw did not let him go." },
  { id: "k-264-the-fog-ray", title: "The fog ray", pay: 1224, kid: true, text: "Max has a fog ray. He hit it. Fog ran out. Ned hid in it. Ned saw no Max. Max saw no ray. \"How do I get it off?\" Ned had the ray in his paw. \"I can hit it for a nut.\" Max had to pay his foe to get his own ray out." },
  { id: "k-070-the-hay-prize", title: "The Hay Prize", pay: 1224, kid: true, text: "Max had a nag for a run. It did not run. Dot set an oat by its lip. It ate. Dot set an oat by the far end of a rug. It ran to it. Max won a cap of hay. The nag ate it too. Max had no cap, but the nag won tea." },
  { id: "k-114-the-hat-in-the-fog", title: "The hat in the fog", pay: 1224, kid: true, text: "Ned had to lie low in his sea tub in fog. Pip had to be mum. Ned saw a rag in the fog. \"Not one cry,\" he did say. The rag got to Ned. Ned did go, \"Ah! Ah!\" Pip got the rag. \"The hat of Ned!\" Ned hid his red ear." },
  { id: "k-229-the-shrink-hat", title: "The shrink hat", pay: 1224, kid: true, text: "Max has a box to get Kit wee. Kit got in. Max hit a red dot. Kit got out. Her hat was wee. Kit was not. Max did try to do it a lot. The hat got wee. Kit put it on a pea. Max did bow to the pea. It was a toy top guy." },
  { id: "k-069-the-bat-bed", title: "The Bat Bed", pay: 1224, kid: true, text: "Gus had to get a bat by a hex. He did say bed. A bed was in the den. Bo did ask him to try bat. Gus did say bat. A bat was in the den too. It had a nap on the bed. Bo put an A on a tag. Gus had got a pet and its cot." },
  { id: "k-261-the-hat-choice", title: "The hat choice", pay: 1224, kid: true, text: "Kit had a red hat and a tan hat. Bo ran in. \"My fig is too hot!\" Kit got the red hat. It did not fit. She got the tan hat. It did fit. Kit ran out to aid Bo. He had put his fig in a tub. Kit had a hat but no job." },
  { id: "k-132-the-quiz-king", title: "The quiz king", pay: 1224, kid: true, text: "Max had to win a cup. Pip sat by him. \"No fur. A lid. You can sit on it,\" the ref did say. Max did not say it. Pip put a paw on the box Max sat on. Pip won. He got the box for his den. Max had to sit on the sod." },
  { id: "k-231-the-red-rope", title: "The red rope", pay: 1224, kid: true, text: "Kit has a red web for Gus in a pit. Gus got it. Kit did tug. Gus got up a bit and hit mud. Kit did tie it to an oak. Gus got out. He got one end of the web up. Kit did hop in it. The web was now a toy for all." },
  { id: "k-266-the-space-seed", title: "The space seed", pay: 1224, kid: true, text: "Max put a nut in his new box. He hit the red dot. An oak got up in it. Dot had to get low. The oak got Max by his hat. \"Get me out!\" Dot cut a bit of the box off. Max got out. His box was now a hut in an oak." },
  { id: "k-121-the-vault-job", title: "The vault job", pay: 1224, kid: true, text: "Dot saw a fig in a box. Pip had a map of the den. He put on a wig to fox the cop. Dot got low. She got the fig. The cop put out a cup. \"One nut,\" he did say. Pip got his wig off. He hid his map in it. \"Can I pay in fur?\"" },
  { id: "k-216-the-oak-key", title: "The oak key", pay: 1224, kid: true, text: "Fay had a key to an oak hut. She hid it in her fur. Gus sat by the hut. Fay got by a log. Her key hit the mud. Gus ran out. \"You can tap,\" he did say. Fay did tap. Gus let her in. Her spy hut had no use for a key." },
  { id: "k-097-the-ant-rescue", title: "The Ant Rescue", pay: 1248, kid: true, text: "Max got a paw in a net. He did tug. It did not go. Dot did tug. It did not go. An ant bit a bit of net. The net let Max go. Max put a gem by the ant. It got a nut, not the gem. Max bit the gem. \"Ah. I see.\" Dot got him a nut." },
  { id: "k-256-the-slow-reply", title: "The slow reply", pay: 1248, kid: true, text: "Max got Fay a spy bot. \"Ask it for the key.\" Fay did ask. The bot put a pea in her paw. Fay did ask a lot. The bot put a pea on her wig. Max saw the pea. \"It has a bad ear.\" Max put a key by it. The bot ate a pea. Fay got the key." },
  { id: "k-131-the-prize-door", title: "The prize door", pay: 1248, kid: true, text: "Fay had a red box and a tan box. Bo had to get one to win a cup. Bo got red. It had a mop. He got tan. It had a wet rug. \"No!\" Bo did say. He put the mop and rug by the cup. \"You can win it all now,\" he did say to Fay." },
  { id: "k-133-the-big-spin", title: "The big spin", pay: 1248, kid: true, text: "Kit had a rim on a rod. He hit the rim to win a pie. It got off the rod and did zip to a pie inn. Dot ran to get it. Kit got the pie. Dot got the rim. Kit did ask for a new go. Dot put the rim on his pie. \"Hit it now.\"" },
  { id: "k-276-the-tan-cap", title: "The tan cap", pay: 1248, kid: true, text: "Max had no red cap. Gus saw a red dot on a log. He ran by it to a cup. Max had put his cap in the cup. Gus got it up. It was tan. \"A new cap!\" Max saw his tan dye by the cup. Gus had got the cap and a way to dye it." },
  { id: "k-282-the-dry-clue", title: "The dry clue", pay: 1248, kid: true, text: "Gus had to see who ate his jam. Bo had jam on his paw. Gus ran to get his map. Bo put his paw in a tub. No jam! Gus saw no jam on Bo. But Gus saw his jam jar in the tub. \"You can rub my jar now.\" Bo got a rag." },
  { id: "k-059-the-ice-seat", title: "The Ice Seat", pay: 1248, kid: true, text: "Bo had a bed of ice. Dot ran in. She had hot tea. Bo set the cup on his bed. The ice got wet. The bed got low. Bo sat on the sod. Dot got him a box. Bo put a rug on it. Now he had a dry bed and a cup of tea on ice." },
  { id: "k-171-the-sleeping-cargo", title: "The sleeping cargo", pay: 1248, kid: true, text: "Ned saw a cot in a hut. He got in to get it. Kit was on it in a nap. Ned got the cot to his den. Kit got up. \"Tea,\" she did say. Ned got tea. \"A bun too.\" Ned got a bun. Kit had her nap. Ned had a cot, but no way to use it." },
  { id: "k-225-the-glow-mask", title: "The glow mask", pay: 1248, kid: true, text: "Kit has a red hat. It can get lit. Fay got ill. Kit lit her hat to get Fay to her hut. At six Kit got to a fig hut. Her hat lit up. \"Hi, Kit!\" all did cry. Kit hid it in a bag. The bag lit up. So it was not a spy hat." },
  { id: "k-228-the-odd-print", title: "The odd print", pay: 1248, kid: true, text: "Gus saw one big paw dot and one wee paw dot in the mud. Was a big guy out for a run? Bo sat on a log. He had one hat on his toe. Gus ran up. Bo got it off his toe. Gus saw a big dot in the mud. The big guy was a hat!" },
  { id: "k-235-the-lens-fog", title: "The lens fog", pay: 1248, kid: true, text: "Gus saw a fog in his gem. Pip saw tan sky. Gus did aim at a sea. Fog! He did aim at his toe. Fog! Pip got the gem and did rub it. Gus had put hot tea on it. The fog was out. Gus got a rag for his kit. Pip got the tea." },
  { id: "k-246-the-tip-jar", title: "The tip jar", pay: 1248, kid: true, text: "Fay put a key in a jar at a tea hut. Gus was to get it. He put a nut in the jar. Fay got in. The key had a nut on it. Gus had put all his pay in a tip jar. Fay got the key and a pie. Her spy job had got pay for tea too." },
  { id: "k-259-the-tiny-town", title: "The tiny town", pay: 1248, kid: true, text: "Max had a wee hut in a pan. Ned put a rod in it. \"A big jet!\" Max did cry. He put a net on it. Ned got the rod up. The net hit a hut. Max had to fix it. Ned got a tea cup. \"A new sea!\" Max put a toy sub in it. Ned had no tea now." },
  { id: "k-267-the-spy-sneeze", title: "The spy sneeze", pay: 1248, kid: true, text: "Fay hid in a hat hut. Kit had a wig for her. Fay put it on. A bit of fur got on her lip. \"Ah!\" Fay did cry. Kit got it off. Fay put a nut in the wig to pin it on. The nut hit her toe. \"Ah!\" Fay had to be a spy in a cap." },
  { id: "k-279-the-space-toll", title: "The space toll", pay: 1248, kid: true, text: "Ned put a rim by a red orb. \"Pay a nut to get by.\" Dot had no nut. She had an oak in a pot. Ned got it. Dot got by. Ned had to add dew. Dot ran up, a cup in her paw. \"Can I get a nut?\" Ned sat by his oak. It had no nut yet." },
  { id: "k-073-the-royal-toe", title: "The Royal Toe", pay: 1248, kid: true, text: "Max had to put a paw in ink for a law. He put his paw on a tag. The tag was all red. The law was hid. Dot got him a new tag. Max put one toe in ink. It fit. Dot had his law. \"My toe has a job,\" Max did say. \"My paw has a nap.\"" },
  { id: "k-222-the-map-fold", title: "The map fold", pay: 1248, kid: true, text: "Fay has a map in a can. Bo bid her cut it by the red ink. She did. Bo put the map in a box. He put a fig in it too. \"Get it to Dot.\" Fay saw the way now. It was not far to a mat. Her spy job was to put a fig in a box." },
  { id: "k-242-the-ice-hut", title: "The ice hut", pay: 1248, kid: true, text: "Ned has a hut of ice. His aim is on the ice. Kit can see it. He is to get her in a pit. Kit put a log on it. Ned ran out to tip her in. He hit the log and sat low. Kit put a rug on his ice. His aim was hid now." },
  { id: "k-253-the-ice-tag", title: "The ice tag", pay: 1248, kid: true, text: "Fay cut a spy tag in ice. Gus was to get it at six. Fay put it in the sun by his hut. At six Gus got a wet mat. Fay saw no ice. \"Did you get the tag?\" Gus did nod. \"Yes. I am to mop.\" He got a mop. Fay had to mop too." },
  { id: "k-102-the-mud-run", title: "The mud run", pay: 1248, kid: true, text: "Bo ran up an oak. Max sat in mud. At the big run, the ref put a tub at the end. Bo ran so far he did not see it. Max got up to get him. His paw hit the tub. Max won. He put mud in the cup. Bo got a mud pie." },
  { id: "k-106-the-pie-hat-prize", title: "The pie hat prize", pay: 1248, kid: true, text: "Kit put his pie up on a box for the ref to see. The air got the pie to Dot. She put it on her ear as a hat. The ref saw her. He did say Kit had won the hat cup. Dot ate the rim of her hat. Now it did not fit." },
  { id: "k-233-the-false-code", title: "The false code", pay: 1248, kid: true, text: "Fay got a rap in a hut. She put it on her pad. Max had a nap by a pan. His toe hit it as he lay on his cot. Fay got him up to ask for the spy key. He had no key. She put the pan on a peg. No rap! The spy was a toe." },
  { id: "k-277-the-safe-seat", title: "The safe seat", pay: 1248, kid: true, text: "Fay hid in a big box. Ned sat on its lid. Fay had to get out. She did rap. Ned did not get up. He put a rug on the lid. \"A fun cot!\" Fay did rap a lot. Ned got up. Fay ran out. Ned put ink on a tag. \"Cot for you. It can rap.\"" },
  { id: "k-239-the-spy-scent", title: "The spy scent", pay: 1248, kid: true, text: "Fay has a kit you may not see. She got in the hut of Pip to get a spy tag. \"Is it hot tea?\" Pip did ask. Fay had a cup. \"Yes,\" she did say. \"You are by my bed!\" Pip put a tag by the cup. Fay got it. Her tea was bad spy kit." },
  { id: "k-241-the-hat-hunt", title: "The hat hunt", pay: 1248, kid: true, text: "Dot had a hat she did not see. Gus saw a bit of oak on a rug. He ran to an oak. Dot had put her hat on it. It had a nut, a fig, and fur in it. Bo lay by it. It was his tea bed. Dot got her hat. Bo had to use a pan." },
  { id: "k-118-the-dry-well", title: "The dry well", pay: 1272, kid: true, text: "Pip got to a pit to get a sip. Ned had a cup. \"No tea in it,\" Ned did say. Pip got a rod. The rod hit a lid. Ned had put it on the pit. Pip got the lid off. Ned got a sip. \"A new pit!\" Ned did say. Pip put the lid on. \"Now it is old.\"" },
  { id: "k-287-the-lost-badge", title: "The lost badge", pay: 1272, kid: true, text: "Gus had no tag on his bag. Dot saw a pin on a pie. Gus had set the pie by his tag. He got the pin up. The pie got up too. Dot put a cup by it. Gus got his tag off the pie. Now his tag had jam. He had to use a new tag." },
  { id: "k-028-the-full-flight", title: "The Full Flight", pay: 1272, kid: true, text: "Max had a hex in ink. It did say to add tea, fig, and egg to a pot. Dot did it. Max did say a hex to fly. The pot did not fly. Dot ate a bit. Max ate too. \"We can fly in a bit,\" Dot did say. Max had to sit. His hex had fed him." },
  { id: "k-244-the-coin-ship", title: "The coin ship", pay: 1272, kid: true, text: "Bo put a fee in his toy jet. It had a hum. Fay had a sun hat. The two saw a red orb on its map. The jet was off. Bo had no fee. Fay put a nut in it. No hum. The two sat on a red rug. Now the rug was a red orb. It had no fee." },
  { id: "k-023-the-low-flight", title: "The Low Flight", pay: 1272, kid: true, text: "Bo sat on a mop. \"Fly!\" The mop did not fly. Gus put it on a toy jet. The jet did fly. The mop got up a bit. It hit a rug. Bo got the mop wet. Now it did a job. He put the jet on a peg. A mop had to fly low to get mud off a rug." },
  { id: "k-271-the-red-gem", title: "The red gem", pay: 1272, kid: true, text: "Ned put a red nut in a box. \"It is an odd gem!\" Gus did not pay. He put it in his tea. The tea got red. Gus got the nut up. The red was jam. Ned had no odd gem now. Gus got a nut. Ned got a cup of jam tea, not a bag of pay." },
  { id: "k-300-the-great-finale", title: "The great finale", pay: 1272, kid: true, text: "Pip got to a red orb in his jet. Dot had a red rag on a pin for him. \"You won!\" Pip got the pin in his paw. It was too big for the jet. Dot put it in a cup and put tea in it. Pip got the cup. His big win was a cup of tea." },
  { id: "k-212-the-tiny-sun", title: "The tiny sun", pay: 1272, kid: true, text: "Fay has a sun in a jar. Ned put his toy jet by it. The jet got hot. Fay put the jar on ice. The ice got wet. Ned put the jar by his bed. He can see his map now. At ten Fay put a lid on the jar. The sun got to nap too." },
  { id: "k-123-the-safe-code", title: "The safe code", pay: 1272, kid: true, text: "Fay hid a bun in a box. Gus had a key. He put his ear to the box. \"Tic, tic!\" he did say. Fay did ask why a bun did tic. Gus got the lid off. A toy was by the bun. Fay had put it in. Gus ate the bun. \"Yum! I win the bun and its toy.\"" },
  { id: "k-189-the-pie-countdown", title: "The pie countdown", pay: 1272, kid: true, text: "Bo saw a box go tic. Max hid by a log. Bo had to hit a red peg to aid Max. He hit it. The box did not tic. Max got out. He got the lid off. It had an icy pie. It was a pie box, not a bad box. Bo did bow. Max ate icy pie." },
  { id: "k-129-the-old-ruin", title: "The old ruin", pay: 1272, kid: true, text: "Ned saw ink on a bar. Kit had a pad. He did say the ink was a map to ore. Ned dug and dug. Kit saw TEA on the pad. It did not say ORE. The ink led to an inn. Ned got tea. Kit got to fix the pit. Ned let him use his cup." },
  { id: "k-137-the-red-rag-quest", title: "The red rag quest", pay: 1272, kid: true, text: "Dot had no red rag. Bo ran to aid her. The two dug in a box and in the jam pot. Bo put the box and pot on a map. Dot sat for a nap. Bo saw the rag on her leg. He put DOT on the map. Dot put BO by it. \"I got you too!\"" },
  { id: "k-283-the-pit-prize", title: "The pit prize", pay: 1272, kid: true, text: "Fay was in a pit. Kit had won a big cup. She set it by the pit to aid Fay. Fay got in it. Kit got it up. Fay sat in the cup all day. \"I am the top pal now!\" Kit put it up on a box. Fay had to get out to go to bed." },
  { id: "k-046-the-running-bun", title: "The Running Bun", pay: 1272, kid: true, text: "Kit had a hot bun. It ran off a pan and by a cot. Max ran to get it. He put a tin by the cot. The bun ran in. Kit put an eye on it in jam. It had to see Max eat a bit. It did not run now. Max put jam on its new lip." },
  { id: "k-185-the-prize-portrait", title: "The prize portrait", pay: 1272, kid: true, text: "Max won a cup. Kit had put Max on a pad in ink. Max saw it. It had his fur and ear, but no eye. \"No eye!\" he did say. Kit got a new pad. \"You did not see me.\" Max sat so Kit saw his ear. Kit put an ear on the new pad too." },
  { id: "k-214-the-gum-trap", title: "The gum trap", pay: 1272, kid: true, text: "Ned put gum on a mat to get Pip. Pip saw it and ran by. Ned ran to see how he did it. His fur got in the gum. Pip got his arm. The mat got up too. The two had to hop to the tub. Ned had to ask his foe for aid." },
  { id: "k-251-the-space-jam", title: "The space jam", pay: 1272, kid: true, text: "Bo put his toy jet on a log. Pip had a jar for the gas. Bo did ask for it. Pip put jam in the jet. Bo hit the red dot to go. The jet did not go. Pip ate jam off the rim. \"I can eat the gas!\" Bo got a cup to get jam out." },
  { id: "k-064-the-little-hat-shop", title: "The Little Hat Shop", pay: 1272, kid: true, text: "Kit had a rag to sew for a cap. At ten, Bo got it. He cut it up. He did sew a cap for an ant, a cap for a bee, and a cap for a fly. At six, Kit saw the ant, bee, and fly in a row. All had a cap. Kit put a bag on her top. \"Now I fit in.\"" },
  { id: "k-226-the-soft-launch", title: "The soft launch", pay: 1296, kid: true, text: "Bo has a jet in a box. Pip got in, a pad on his lap. Pip did not let Bo get on the pad. Bo got one end. Pip got the far end. The two did tug. The box did rip. Bo got a bit of a pad. Pip got a bit too. The big war got the two a bed." },
  { id: "k-275-the-hero-net", title: "The hero net", pay: 1296, kid: true, text: "Dot was in a pit. Kit had a net to get her out. Kit put it by Dot. Dot got in. Kit did tug. A nut in her bag got in too. Dot ate it. Kit got her up. Dot got out. \"Can I get in it?\" she did say. Kit put the nut bag in a box now." },
  { id: "k-285-the-sea-key", title: "The sea key", pay: 1296, kid: true, text: "Fay got a key off Bo. She hid it in her cup. Bo put tea in the cup. Fay saw no key. \"It is in a sea!\" Bo got her a rod. Fay got the key out. It was wet but in her paw. Fay put the key in a bag. Bo got his cup of tea now." },
  { id: "k-040-the-fig-feast", title: "The Fig Feast", pay: 1296, kid: true, text: "Fay had to eat a lot. Gus had one fig. He cut it up. Fay had one bit. Gus had one bit. It was not a lot. Fay got her bag. It had a big fig pie. Gus cut it up. Fay ate a lot now. Gus put his fig nub on a tin. It was art, not tea." },
  { id: "k-090-the-rug-landing", title: "The Rug Landing", pay: 1296, kid: true, text: "Ned had a rug. It did fly. He had to get it to sit. He put a net on it. The net did fly too. Bo put a pot on it. The rug sat. Ned put tea in the pot. Now his rug was a mat for tea. Bo put a tag on it: Do not fly at tea." },
  { id: "k-166-the-wanted-hat", title: "The wanted hat", pay: 1296, kid: true, text: "Fay put a hat on a peg. Kit put up a tag to get a bad guy. It had the hat on it. Fay saw the tag. She got Kit the hat. Kit put it in a pen. Fay had a new hat at the inn. Kit did nod. The old hat got a pot of tea. Fay got no tea." },
  { id: "k-243-the-slow-beam", title: "The slow beam", pay: 1296, kid: true, text: "Pip got a ray to fix a fig in the air. Max let a fig fly to him. Pip did use the ray. The fig was in the air. Pip had to sit to eat. Max ate and had a nap. Pip cut the ray off. The fig hit his lip. To eat, you may let a fig go." },
  { id: "k-257-the-new-planet", title: "The new planet", pay: 1296, kid: true, text: "Dot had a map in her jet. A red pea was the new orb. Pip ate it. Dot saw no red pea. \"We ate an orb!\" Pip had to say he ate it. Dot put a fig on the map. Pip ate it too. Dot put a pin on the map. Pip got a fig to eat, not a map." },
  { id: "k-081-the-royal-parcel", title: "The Royal Parcel", pay: 1296, kid: true, text: "Bo hid in a box for fun. Pip did not see Bo. He put a tag on it: To Bo. Ned got it. \"It is for Bo.\" \"I am Bo!\" Ned got the lid up. Bo got out. Ned put the box by Bo. \"I got it to you. You got out of it. My job can end.\"" },
  { id: "k-086-the-net-champion", title: "The Net Champion", pay: 1296, kid: true, text: "Pip had one end of a net. Dot had one end. A tug of war was on. Pip did tug. Dot did tug. Bo sat in the net. Now no one won. Pip and Dot put the net by a bed. Bo did not get up. He got his nap in the net. \"I won,\" he did say." },
  { id: "k-087-the-paper-fox", title: "The Paper Fox", pay: 1296, kid: true, text: "Kit had to do a hex on a tag. She cut it to be a fox. Bo did ask it to run. It did not run. He did ask it to sit. It did not sit. Kit put a cup on it. \"My fox has a job.\" Bo put an A on it. The fox was a mat for his tea." },
  { id: "k-103-the-ice-star", title: "The ice star", pay: 1296, kid: true, text: "Dot had to win an ice cup. Gus had to mop the ice. Dot did try to hop. Her paw hit the mop. Dot sat on it. Gus did tug it by a tie. Dot did ski by the ref on the mop. She won the cup. Gus got tea in it as his fee." },
  { id: "k-161-the-pirate-dad-flag", title: "The pirate dad flag", pay: 1296, kid: true, text: "Bo put BAD on a rag for his sea tub. Dot got a pen. She put DAD on it. Gus saw the rag and ran to Bo. \"My boy!\" he did say. He put a bib on Bo and got him a bun. Dot hid her pen. Bo got the rag off. Gus put it on the bib." },
  { id: "k-067-the-royal-cat", title: "The Royal Cat", pay: 1296, kid: true, text: "Kit let Bo use her cat to get a rat. Bo put the cat in his den. It had a nap. The rat had a nap by it. Now no one ate his pie. Bo had a nap too. Kit got a tin of tea for her cat. The cat did not get up. It had a job to nap." },
  { id: "k-126-the-deep-cave", title: "The deep cave", pay: 1296, kid: true, text: "Kit and Max got in a pit. A low din was in it. Kit lit a log. Max hid. The din did not end. Kit saw Max had no bun. He fed Max a fig. The din did end. Kit put a bad guy on the map. Max put a fig by it. \"It can eat the fig, not us.\"" },
  { id: "k-138-the-grand-feast", title: "The grand feast", pay: 1296, kid: true, text: "Kit set a big box for tea. Ned had his top bow on. Kit did a jig. A nut hit the sod. Ned sat on the rug. Kit sat too. The two ate by the box. Kit put one nut on it. Ned got up on the box to eat it. Now the box had a pal too." },
  { id: "k-195-the-ice-oracle", title: "The ice oracle", pay: 1296, kid: true, text: "Fay had an ice orb to see a new day. Kit put a nut in her cup. Fay saw the wet orb. \"A wet day,\" she did say. Kit got a mat to sit dry. The sun was hot. Fay had a wet rug, not an orb. Kit sat on her mat. \"You got the wet day, not me!\"" },
  { id: "k-258-the-loud-award", title: "The loud award", pay: 1296, kid: true, text: "Kit won a tin pot for her big act. Fay had to get by Gus. Kit ran to aid her. The pot hit a log. Fay hid in a box. Kit put the pot in it too. Now the box had a din. Fay got out and set it by Gus. Kit had to win a rug, not a pot." },
  { id: "k-263-the-new-airlock", title: "The new airlock", pay: 1296, kid: true, text: "Bo has a jet in a box. Dot has to see if its gap is big. Bo got in. His big hat did not fit out. \"I am the top guy!\" Dot put a cup by him. \"Tea is out by me.\" Bo got his hat off. The gap was not bad. The top guy was too big." },
  { id: "k-116-the-hungry-art-judge", title: "The hungry art judge", pay: 1296, kid: true, text: "At ten Fay met Bo by an oak. Bo had a pen. Fay had one too. \"I can win,\" Bo did say. He put an oak on his pad in ink. Fay put a pie on her pad. Gus saw the art. He put an X by the pie. \"No pie for me? So no cup for you!\"" },
  { id: "k-173-the-jewel-audition", title: "The jewel audition", pay: 1296, kid: true, text: "Bo had a wig to get a gem. Fay had the gem on a box. Bo did a jig so she did not see his paw. Fay got him a rag. \"You can rub the gem for me.\" Bo had to rub it all day. Fay got him a nut as his pay. Bo had no gem. He had a job." },
  { id: "k-249-the-soft-rod", title: "The soft rod", pay: 1296, kid: true, text: "Pip got a rod out of a pot. Ned did bow. \"You are our top guy!\" Pip did try to cut a bit of oak. The rod did bow. It was gum. Pip did use it to get a fig off a peg. It hit his hat. Ned did bow a lot. A guy who can get tea is a fun guy." },
  { id: "k-272-the-giant-pea", title: "The giant pea", pay: 1296, kid: true, text: "Max put a pea in his ray box. He hit the red dot. The pea was as big as his hut. Kit was by the gap. The pea hid it. \"How do we get out?\" Max got a rod. Kit got a cup. The two ate a way out. Max had no use for a big pea at tea." },
  { id: "k-273-the-sos-snack", title: "The SOS snack", pay: 1296, kid: true, text: "Pip put SOS on his toy jet. Fay ran up to aid him. \"Are you ill?\" Pip did not nod. He had a fig and a cup. \"I ask for jam.\" Fay got him a jam jar. Pip got SOS off the jet. Fay put it on her bag. Now she had no jam for her own fig." },
  { id: "k-252-the-hero-tax", title: "The hero tax", pay: 1296, kid: true, text: "Kit sat by a gap in the way. \"I can get you up!\" Ned had a bag and a fig. Kit got him up in the air. He ate a bit of it on her paw. \"Pay me a fig,\" Kit did say. Ned did not get off. Kit had to eat too. He let her buy a bit for a nut." },
  { id: "k-055-the-royal-pan", title: "The Royal Pan", pay: 1320, kid: true, text: "Dot put her cap on a peg. Fay put a pan on her top. Max saw Fay. \"Sir Fay!\" He did bow and got her a fig. Dot had to rub mud off a pan. Fay put her pan on a peg. Max did bow to the peg. Dot put her cap on her pan. Max got it a fig too." },
  { id: "k-074-the-fan-hex", title: "The Fan Hex", pay: 1320, kid: true, text: "Gus put a tag on a peg. A fan let it fly. Gus did say a hex to get it low. It did not get low. Bo hit a pin on the fan. The fan did not run. The tag got low. Gus put the pin in his kit. \"A hex in a pin!\" Bo put the fan in the kit too." },
  { id: "k-289-the-royal-pet", title: "The royal pet", pay: 1320, kid: true, text: "Bo had a bot on his red orb. \"Bow!\" The bot did bow. \"Bow!\" It did bow a lot. Bo sat on his cot. Max put a nut by the bot. The bot ate it. \"It is my fan,\" Bo did say. Max put a nut by his own cot. The bot ran to Max. It was a nut fan." },
  { id: "k-051-the-egg-password", title: "The Egg Password", pay: 1320, kid: true, text: "Bo had a job by a gap. All had to say egg to go in. Pip did not see how to get in. \"How can I go in?\" \"Say egg,\" Bo did say. Pip did say egg. Bo let him by. Pip put a tag up. It had egg on it. All got in. Bo had to use fig." },
  { id: "k-050-the-yam-coach", title: "The Yam Coach", pay: 1320, kid: true, text: "Dot was to go to a hop. Fay hit a yam to get a car. It was yet a yam. She hit it to get a nag. It was yet a yam. Dot put it in a pot. It was tea now. Fay got jam for it. Dot and Fay ate. No car had to go to a hop in her own den." },
  { id: "k-172-the-rug-trail", title: "The rug trail", pay: 1320, kid: true, text: "Pip had to get a red rug out of a den. Dot was the cop. Pip put it in a bag. One end got out. The end was by the den. The bag was by Pip. Dot ran on the rug to him. Pip put a bow on it. \"For you!\" Dot put a tie on Pip. \"For you too!\"" },
  { id: "k-048-the-paid-tin", title: "The Paid Tin", pay: 1320, kid: true, text: "Fay had a tin to see her eye. She did ask who had the top hat. Kit got a rag. She got the fog off the tin. Fay saw her cap. She did ask who had the top hat now. Kit put a hat on the tin. Fay saw no one. Kit got a fig to get it up." },
  { id: "k-286-the-oil-bot", title: "The oil bot", pay: 1320, kid: true, text: "Max has a bot to get a lid up. Kit did ask to see it. The bot put oil by the lid. It hit a pot. Oil got on a mat. Max had oil on his paw. He hit the mat. Kit got him up. Max put the bot by his toy car. It can oil the car now." },
  { id: "k-297-the-odd-egg", title: "The odd egg", pay: 1320, kid: true, text: "Dot had a tan egg in a box. Gus saw it. His egg was tan too. \"Did you get my egg?\" Dot had a pot of tan dye. Gus saw a rod by it. He got the egg up. It had a cut. Dot cut it up. It was a nut. Gus had to get his egg out of his bag." },
  { id: "k-030-the-pie-map", title: "The Pie Sun", pay: 1320, kid: true, text: "Pip had to do art of the sun. Fay had to do it too. Pip got ink. Fay got pie. Pip put a dot in his art. Fay put a nut on her pie. At six, all had a sun. Fay ate her art. \"Why did you eat the sun?\" Pip did ask. \"It set,\" Fay did say." },
  { id: "k-042-the-tin-key", title: "The Tin Key", pay: 1320, kid: true, text: "Pip got a key. Kit saw it was tin. \"A den may get a gem!\" Pip did try a box. No fit. He did try a jar. It did fit. Kit saw a nut. Pip ate it. Kit got one too. Now the gem was in a gut. Pip put the key in the jar. No one had to dig for it." },
  { id: "k-127-the-vine-cafe", title: "The vine cafe", pay: 1320, kid: true, text: "Gus saw a tie by a gap. Bo got on it. He did hop to an oak. Gus did not go. Bo fed him a fig. Gus ate it. \"I am to get by the gap,\" Gus did say. Bo fed him two. Gus ate the two too. \"No,\" Gus did say. \"I can sit by the gap and eat.\"" },
  { id: "k-141-the-red-carpet", title: "The red carpet", pay: 1320, kid: true, text: "Fay had a red rug for Dot. Dot had her top hat on. She ran on the rug and did bow. Mud got off her paw. The rug was tan. Fay put it by the mud pit. Now all ran on it. Dot did bow to all. Her rug was not red, but her ear was." },
  { id: "k-284-the-jet-bid", title: "The jet bid", pay: 1320, kid: true, text: "Ned was to let a guy buy a jet. Pip ran in to see him. Pip put his paw up to say hi. \"You won!\" Ned put the jet by him. Pip had to pay a nut. Pip put his paw up to say bye. \"A new jet!\" Ned did cry. Pip hid his paw in his bag now." },
  { id: "k-045-the-bee-adviser", title: "The Bee Adviser", pay: 1320, kid: true, text: "Dot had a bee on her cap. She did ask how to do her job. It did hum. Ned put a pea in a pot. The bee did hum. Ned ate a bun. The bee got off. Dot put a bud on her cap. A new bee sat on it. Now Dot did not ask him how. She let it eat." },
  { id: "k-247-the-mud-bot", title: "The mud bot", pay: 1320, kid: true, text: "Max has a bot to mop mud. Dot put a mop in its paw. It can mop a bit. Its fur put mud on it as it ran by. Dot got a rug for it to use. No mud! Max had to cry for joy. The bot did bow and got in the tub. Dot had to mop now." },
  { id: "k-255-the-car-lift", title: "The car lift", pay: 1320, kid: true, text: "Bo sat in a car on a log. The car ran off. Kit ran to aid him. She put a rug in its way. The car got on the rug. Kit got it up. Bo was in a bag of rug now. \"I am not a fig!\" Kit let him out. Bo got to his hut, his car in his lap." },
  { id: "k-260-the-secret-song", title: "The secret song", pay: 1320, kid: true, text: "Fay had to hum to get Bo to get a key. She hid by an oak and did hum. Bo had a pot. He hit it to her hum. Fay did hum a lot. Bo did jig. Fay got up to ask for the key. Bo put it in her paw. \"We can hum and jig at tea!\"" },
  { id: "k-151-the-bowling-bow", title: "The bowling bow", pay: 1320, kid: true, text: "Pip had to hit a pin row. Kit put a bow on a pin. Pip had an orb in his paw. He did not lob it. Kit did ask why. Pip put the orb on the sod and sat by the pin row. \"It is an act now,\" he did say. Kit got a bow for the orb too." },
  { id: "k-124-the-decoy", title: "The decoy", pay: 1320, kid: true, text: "Bo put a mud pie on a box to fox Ned. Ned got all to see it. Bo hid by an oak and ate a fig pie he had got off Kit. Ned won a cup for the mud pie. Bo did go to Ned. \"It is my pie!\" Ned let Bo get the cup. It was mud too." },
  { id: "k-238-the-star-queue", title: "The star queue", pay: 1320, kid: true, text: "Ned sat at the way to a toy sun. Bo had to get by him. He got a rod of tin. Ned put up one paw. \"Get a tag.\" Bo got one. He was two. Dot was one. She had a go on the sun toy. Bo put his rod low. A go in a row was fun. A war was not." },
  { id: "k-288-the-hero-lift", title: "The hero lift", pay: 1320, kid: true, text: "Ned had a big log on his lap. Kit got it up. Ned put a cup on it. Kit had the log up. Ned put a pie by the cup. Kit did not let go. \"You can eat now,\" he did say. Kit had to sit, the log on her lap. She was a top pal and a tea mat." },
  { id: "k-290-the-spy-queue", title: "The spy queue", pay: 1320, kid: true, text: "Fay put a spy tag by a fig hut. Pip was to get it. Ten sat in a row. Fay saw Pip at the end. She got him a tag. Pip did not go. \"No! It is my go!\" Gus did cry. Fay got a fig. She put the tag in a bag and got it to Pip as he ate." },
  { id: "k-237-the-hat-fan", title: "The hat fan", pay: 1320, kid: true, text: "Kit can fan a big red hat. Dot had a hot bun. She may not eat it yet. Kit got in to aid her. The hat put air at the bun. Kit hit it as she ran by. Bo ate it out of the air. Dot put the hat on Bo. \"You can fan my new bun.\"" },
  { id: "k-245-the-dark-lamp", title: "The dark lamp", pay: 1320, kid: true, text: "Ned got his hut dim. Kit ran in, a jar of sun in her paw. No ray! Ned had to cry for joy. Kit got the cap off the jar. The hut lit up. Ned was in a rug. Kit let him use his hat. A foe has to get up to put on his hat for a war." },
  { id: "k-089-the-polite-rod", title: "The Polite Rod", pay: 1344, kid: true, text: "Fay had a rod. \"Get the cup.\" It did not go. \"Get the pot.\" It did not go. Dot did ask, \"May I use you?\" The rod did hop. It got the cup. Fay put a bow on the rod. \"May I?\" The rod did bow. It got the pot. Dot put tea in it. The rod got a cup too." },
  { id: "k-080-the-fox-alarm", title: "The Fox Alarm", pay: 1344, kid: true, text: "Kit did cry, \"Fox!\" Gus ran to see. He saw no fox. Kit did cry, \"Fox!\" Gus ran to see. He saw no fox. A fox sat by Kit. Kit did cry. Gus did not run. The fox put a fig by Kit. She ate it. Gus got a fig too. Kit did cry, \"Tea!\" Gus ran for a cup." },
  { id: "k-178-the-jungle-echo", title: "The jungle echo", pay: 1344, kid: true, text: "Dot got to a pit. Max sat by an oak. \"I win!\" Dot did say. \"I win!\" the pit did say. Dot got a rod out. Max got in. \"Dot is a wit,\" he did say. The pit did say it too. Dot let Max win the pit. He did ask it for tea. It did ask him for tea too." },
  { id: "k-292-the-sky-box", title: "The sky box", pay: 1344, kid: true, text: "Dot had a sun and an orb in her toy sky. Max put the orb in a box. \"We had an orb!\" He put the sun in the box too. Dot saw no sky. She put her paw in the box. It had the sun and the orb. \"The sky is in my paw!\" Max had to nod." },
  { id: "k-079-the-fur-hex", title: "The Fur Hex", pay: 1344, kid: true, text: "Fay had a hex for her fur. It got to her toe. She cut it. It got to her toe. She cut it. Dot did ask if she had to say the hex to end it. Fay did say it. Now she had no fur. Dot got her a rug. Fay put it on. \"I may try a new hex.\"" },
  { id: "k-068-the-bee-piper", title: "The Bee Piper", pay: 1344, kid: true, text: "Ned had to get a bee out of the den. He did hum. The bee did hum. Ned ran out. The bee did fly out. Dot sat to sip her tea. Ned did hum to get in. The bee did hum too. Dot put a cup by the gap. \"Tea for two!\" Ned let the bee sip too." },
  { id: "k-095-the-box-tower", title: "The Box Tower", pay: 1344, kid: true, text: "Ned had to get a hut up in the sky. Pip put a box on a box. Dot put a box in a box. Bo put a box by a box. No one saw a hut in the sky. Kit put a toy in one box. She put a mat in one box. Now all had a den for a toy. Ned put his toy on the top." },
  { id: "k-146-the-sun-box", title: "The sun box", pay: 1344, kid: true, text: "Gus had a box to get to the sun. Max had a fig to eat on it. Gus hit a peg. A fan got his fur up. The box did not go. Max put a sun on a log in ink. He sat on it to eat. Gus had a fan to use. Max had a log. The sun had his fig on it." },
  { id: "k-168-the-pie-bridge-toll", title: "The pie bridge toll", pay: 1344, kid: true, text: "Dot had a van to get by a gap. Gus had a log on it. \"One nut,\" he did say. Dot had no nut. She had a big pie. Gus got the pie. Dot got her van by. Gus sat to eat it. The pie hid the gap. A new van got on the pie. Gus got one nut for a bit." },
  { id: "k-186-the-paired-lifts", title: "The paired lifts", pay: 1344, kid: true, text: "Gus had to run off as Bo was the bad guy. Bo had a tie to get a box up. Gus got in. \"Up!\" he did cry. Bo did tug. The box got up. Gus got out. Bo was by him. Bo had a box too. \"I can go up too!\" Gus did hum. Bo had a nap. Gus got out." },
  { id: "k-291-the-spy-swap", title: "The spy swap", pay: 1344, kid: true, text: "Fay had a red bag. Bo had a tan bag. The two met by a log. Fay got the tan bag. Bo got the red bag. Fay saw no key in it. Bo saw no map in his. Her bag had tea and pie. His had pie too. No spy kit! The two sat by the log to eat." },
  { id: "k-052-the-ant-exam", title: "The Ant Exam", pay: 1344, kid: true, text: "Kit had to get a lid up. She did hum a hex. The lid did not go up. She put a nut by it. An ant ran to it. The nut was at its rim. The ant got the lid up. Fay put an A on a tag for the ant. Kit got a B for the nut. The ant ate the tag." },
  { id: "k-099-the-jig-job", title: "The Jig Job", pay: 1344, kid: true, text: "Bo had a hex for his paw. It did a jig. He had to sit. The paw did a jig. He had to eat. The paw did a jig. Kit put a mop in his paw. Now his jig got mud off the rug. Bo put a cap by his mat. Dot put a nut in it. His jig had a job for tea." },
  { id: "k-113-the-plank-game", title: "The plank game", pay: 1344, kid: true, text: "Max bid Dot go on a log by the sea. Dot put a nut on it. Max put a nut by it. Dot put a fig on it. Max put one too. The log did dip. Dot sat on dry sod. She got her fig off the log. Dot ate her dry fig. Max had to get his wet fig." },
  { id: "k-188-the-rescue-queue", title: "The rescue queue", pay: 1344, kid: true, text: "Ned ran to aid Dot in a big den. Dot had a tag. \"Get one!\" Ned got one. Gus had one too. Ned had to sit in a row by Gus. At the end of the day, Ned had to go in. Dot had got out to get tea. Ned got a cup. His tag was for tea, not Dot." },
  { id: "k-008-the-bare-cap", title: "The Bare Cap", pay: 1344, kid: true, text: "Max had a hay cap. \"No oaf can see it,\" he did say. Pip saw it. The air got it off Max. All did cry in joy. \"It is in the oak,\" Pip did say. Max got it. Pip put a nut on it to pin it to Max. Max ate the nut. The cap was off now." },
  { id: "k-120-the-toy-bus-chase", title: "The toy bus chase", pay: 1344, kid: true, text: "Gus ran to get a bus. Bo had a van. \"Hop in!\" he did say. The two ran to the bus. Gus got on. He sat by a tot. Bo saw it was a toy bus. It did one lap and got to Bo. \"I got you to the bus,\" Bo did say. \"Now you can get me to the den.\"" },
  { id: "k-182-the-price-of-free", title: "The price of free", pay: 1344, kid: true, text: "Ned had to say the fee for a bun. \"One!\" he did cry. Max did cry, \"Two!\" Gus had the bun. Ned did cry, \"Ten!\" Gus put up his paw. \"You do not pay for my bun.\" Ned hid his nut. Max hid his too. Gus ate the bun. Now no one had to pay at all." },
  { id: "k-265-the-red-eye", title: "The red eye", pay: 1344, kid: true, text: "Gus saw a red eye in his hut. \"Who is in my hut?\" It did not say who it was. Pip put a rug on it. The eye got dim. Gus did ask it to go. Pip got the rug off. It was a toy sun in a jar. Gus put a hat on it. \"The eye has to nap now.\"" },
  { id: "k-149-the-brave-knight", title: "The brave knight", pay: 1344, kid: true, text: "Bo had a pot on his ear. Dot did cry for aid in a big den. His oak rod hit a bar and did not get out. Dot got him oil. He got the rod out. Dot had a jar on her paw. She put oil in it. Her paw got out. Bo put his pot on the jar. \"I win!\"" },
  { id: "k-236-the-loud-hush", title: "The loud hush", pay: 1344, kid: true, text: "Max has a box to cut all din. Fay put it in her bag. The box did cry, \"Shh!\" Gus got up. The box did cry a lot. Fay set it by a sea and ran. Gus bid it end the din. It did not end it. Max got a new box. Fay did ask for no din at all." },
  { id: "k-164-the-boarder-bargain", title: "The boarder bargain", pay: 1344, kid: true, text: "Pip got a rod by the sea tub of Gus. He got up it. Gus put a box in his lap. \"One nut,\" Gus did say. Pip put his hat up. \"I am to get, not pay!\" Gus did nod. \"Get the box. It is my old pie.\" Pip got off the rod. Gus got a new pie to eat." },
  { id: "k-176-the-silent-waterfall", title: "The silent waterfall", pay: 1344, kid: true, text: "Fay had a din in her ear by a pit. Ned had a map. The two got in. Fay got wet. Ned had a cup out. The two saw a tap on a bar. Kit sat in a tub. \"My dip!\" she did say. Ned put a spa on the map. Kit put a nut cup out. Fay was wet, so she had to pay." },
  { id: "k-183-the-swapped-prize-pegs", title: "The swapped prize pegs", pay: 1368, kid: true, text: "Dot had to hit a red peg to win. Bo had a tan peg. Dot hit red. The ref fed Bo a fig. Dot hit red for a new go. Bo got a new fig. Bo hit tan. The ref fed Dot a fig. Dot got Bo to hit tan for her. Bo got Dot to hit red. Now the two had tea." },
  { id: "k-294-the-nut-pet", title: "The nut pet", pay: 1368, kid: true, text: "Max had a bot to get a pea. Ned got it a nut. The bot had the nut and did not go. Max got it a pea. It did not let go of the nut. Ned got the nut. The bot did cry. Max put it in its paw. Ned got the pea. Now the nut had a pet and a tin paw." },
  { id: "k-198-the-toolbox-tribute", title: "The toolbox tribute", pay: 1368, kid: true, text: "Gus had to cut oak for a box. Fay had a saw and a peg. Gus cut oak. Fay had it up. Gus put a peg in it. He got the box up. Gus put the saw in it. Fay put a peg in it too. Her big jar did not fit. Gus had got a box for his saw, not her jar." },
  { id: "k-084-the-fog-lesson", title: "The Fog Lesson", pay: 1368, kid: true, text: "Bo did use a hex for fog. Kit hid in it. Gus hid in it. Bo saw no pal. He did use a hex for sun. Kit was on his cot. Gus was on his rug. Kit and Gus had a nap. Bo lay on the sod. He did use his fog hex. Bo hid his nap in the fog." },
  { id: "k-122-the-fake-gem", title: "The fake gem", pay: 1368, kid: true, text: "Max had a wax gem. Kit had a bag. Max got to the gem on a peg. He put the wax one on the peg and got the old one. Kit put the old gem in her bag. The sun was hot. The gem was goo by ten. Max did pat the one on the peg. It was goo too." },
  { id: "k-174-the-missing-getaway", title: "The missing getaway", pay: 1368, kid: true, text: "Gus had to get a box. Max had to run the van. Gus got in the den. \"Go!\" he did cry. Max ran the van off. Gus was yet in the den. He ran for Max. Max ran on. Gus had to run to his den. Gus got to Max at eve. It had a bus tag in it." },
  { id: "k-047-the-gum-toy", title: "The Gum Toy", pay: 1368, kid: true, text: "Gus put gum on a toy. Pip got a paw on it. The paw did not let go. Dot got her paw on Pip. Kit got her paw on Dot. All had to go to a tub. Gus got the gum off. Pip did ask, \"Is it a fun toy?\" \"It got us all in one tub!\" Kit hid the gum." },
  { id: "k-062-the-endless-cup", title: "The Endless Cup", pay: 1368, kid: true, text: "Bo had a cup. He put tea in it. He had all the tea in a sip. He did say a hex. Now tea did not end. He let Dot sip. He let Ned sip. Dot put the cup in a tub. She let tea run out. Bo sat in the tub. His tea had no end, but his job did." },
  { id: "k-293-the-big-arm", title: "The big arm", pay: 1368, kid: true, text: "Kit saw a big arm on her hut. She put her arm up. The big arm got up too. She put it low. The big arm got low. Pip put a mat up to bar the sun. The arm was out. Kit got by the mat. It was up. \"My foe is me!\" Kit did bow to the sun." },
  { id: "k-177-the-compass-lunch", title: "The compass lunch", pay: 1368, kid: true, text: "Bo had a pin in a cup to see the way. Gus had a nut tin. The pin did aim at Gus. Bo got by an oak. The pin did aim at Gus. Gus got the tin up. Bo got to it. Gus let him get a nut. Bo put the tin on the map. Now the way led to tea." },
  { id: "k-018-the-hungry-hat", title: "The Hungry Hat", pay: 1368, kid: true, text: "Pip had a hat. It did cry all the way to a pie den. Gus saw Pip at the gap. He got him a bit of pie. The hat did cry. Gus put a bit in it. It did not cry now. Pip did ask for tea. Gus got a cup for Pip and a cup for his hat. The hat got a nap." },
  { id: "k-139-the-gap-guard", title: "The gap guard", pay: 1368, kid: true, text: "Max was to be a cop by a gap. Fay did ask to go in. Max did ask for a key. Fay did not see it. She ran to a new gap in the hut. Max put a bar in it. Fay got in at the old gap. Max put his hat by it. Now his hat had to be a cop too." },
  { id: "k-269-the-pie-clue", title: "The pie clue", pay: 1368, kid: true, text: "Gus had a pie. Ned had jam on his lip. \"Did you eat my pie?\" Ned did not say yes. Gus got a new pie. \"It is for the guy who ate my old pie.\" Ned put his paw up. Gus put his old pie tin in it. \"You can rub it.\" Ned got the tin, not the pie." },
  { id: "k-156-the-jam-judge", title: "The jam judge", pay: 1368, kid: true, text: "Fay had a jam pot to win a cup. Gus had to try it. He got a paw on the lid. It did not go up. Fay got a paw on it too. The jam did not let go. Gus did say it was top jam. He had not had a bit. \"It can get a ref to sit by it all day!\"" },
  { id: "k-024-the-jam-gem", title: "The Jam Gem", pay: 1368, kid: true, text: "Fay had to get a gem out of a nut. She hit it too far. It ran off her mat to a jar of jam. Max saw it. \"A gem!\" Fay did say it was a nut in jam. Max ate it. He got Fay a gem for her art. Fay put it by the jar. Now the gem was in jam too." },
  { id: "k-027-the-soup-orb", title: "The Soup Orb", pay: 1368, kid: true, text: "Gus saw Fay in a big orb. He saw a rod too. \"You may sip pea tea.\" Fay got the orb up. It was the lid of her pot. Gus saw a pea in it. \"I see my lot too.\" He got a cup. Fay let him sip the tea. Gus put it on his cup. Now the orb hid the pea." },
  { id: "k-270-the-boss-bot", title: "The boss bot", pay: 1368, kid: true, text: "Dot has a bot as top guy in her toy hut. \"Sit!\" it did say. Dot sat. \"Sit!\" Max sat too. \"Sit!\" Dot put the bot on a cot. \"You too,\" she did say. It did not get up. Dot and Max ran out to hop. The top guy had to sit as the two ran and had fun." },
  { id: "k-066-the-midnight-dye", title: "The Midnight Dye", pay: 1368, kid: true, text: "Max saw mud on a rug. At ten, he hid by a bed. Fay and Dot did a jig. Max put red dye by the gap. It got on Fay and Dot. Max had to tap a paw to the jig. It got red too. At six, all had red fur. Max put a rug in his den for a jig at ten." },
  { id: "k-163-the-mutiny-nap", title: "The mutiny nap", pay: 1368, kid: true, text: "Max ran the sea tub. Ned had to row. \"No job!\" Ned did say. He put a tag on the rod. Max let him be the big guy. Ned sat. Max sat too. The tub did not go. The sun got low. Ned had to row to get his tea. Max got a tag too. \"No job for me!\"" },
  { id: "k-016-the-wish-lid", title: "The Wish Lid", pay: 1368, kid: true, text: "Ned met an eel. It let him ask for a toy. Bo did ask him to ask for a big hut. Ned got a lid. The eel hid in the bog. Bo was sad. Ned let him see a bee in his tea. Bo put the lid on. Now the bee had a hut too. Ned got a sip of tea at six." },
  { id: "k-232-the-wax-orb", title: "The wax orb", pay: 1368, kid: true, text: "Pip put his wee sub in a tub. Dot put a bar of wax in its way. The sub got on the bar. Dot let the tub go dry. \"We got to a new orb!\" Pip did cry. Dot put a dry rug by him. His new orb was for a tub. He had to let Dot use it at his dip." },
  { id: "k-184-the-talent-mop", title: "The talent mop", pay: 1368, kid: true, text: "Pip had to do an act. Fay sat by him as the ref. Pip put a nut in a cup. He put a lid on it. He hid by a mat. Pip got the nut out. Fay did not see it. Pip did bow. Fay got him a mop. \"You got the nut out, but all the mud is on my rug.\"" },
  { id: "k-223-the-egg-alarm", title: "The egg alarm", pay: 1368, kid: true, text: "Gus has an egg in a tin box. Kit has to sit by it. At six, Gus hit a pot. Kit put a net by the hut. Gus ran in. Kit did not let him by. \"I am to eat,\" he did say. Kit saw his tin rod to eat the egg. She got the egg. \"The top guy is me!\"" },
  { id: "k-298-the-hero-knot", title: "The hero knot", pay: 1392, kid: true, text: "Fay had to tie a web to a cot. Kit ran in to aid her. \"I am in!\" she did cry. Kit got her paw in the web. Fay did tie the web to the cot. Kit did bow. The web did tug. Kit sat. Fay had Kit in a web on the cot. \"I am in,\" Kit did say. \"I am in a web!\"" },
  { id: "k-075-the-huge-yam", title: "The Huge Yam", pay: 1392, kid: true, text: "Pip had a yam in the sod. He did tug. It did not get up. Dot did tug Pip. Bo did tug Dot. Ned put tea in the sod. It got wet. The yam got up. Ned had no tea. All had a yam. He put it in the pot. Now all had yam tea. Bo had a mug of mud." },
  { id: "k-117-the-nut-herd", title: "The nut herd", pay: 1392, kid: true, text: "Dot put a nut bag in a van. She had to get it to the inn. Max had to sit on it. Max hit a peg. The van ran to the inn. Dot ran for it. The inn got its nut bag. Max sat on Dot. She had to get him to the den. He got to sit at the end." },
  { id: "k-143-the-tea-monster", title: "The tea monster", pay: 1392, kid: true, text: "Max hid in an oak for an act. Bo had to run as Max did cry. Max did go, \"RAH!\" Bo ran to him. He had tea in a cup. \"Tea for a big cry,\" he did say. Max had a sip. Max did ask for tea in a low cry. Bo ran to get it. The act had a big run yet." },
  { id: "k-054-the-royal-bow", title: "The Royal Bow", pay: 1392, kid: true, text: "Pip had to tie a bow on a box. He had a rag. He did tie one end to a paw. He did tie one end to an ear. Ned saw a bow, but no box. Pip did not nod. His ear had to tug his paw. Ned cut the rag and put it in the box. \"A bow kit!\" Pip did nod now." },
  { id: "k-078-the-fan-and-the-pie", title: "The Fan and the Pie", pay: 1392, kid: true, text: "Bo had to get a cap off Pip. He got a fan. Pip put a paw on his cap. Dot got a hot pie. Pip put his cap by her to eat. Bo got his fan off. He ate pie too. Dot put the pie tin on her top. Now Dot had a cap too. No one did try to get it off." },
  { id: "k-110-the-egg-act", title: "The egg act", pay: 1392, kid: true, text: "Pip did lob an egg up for a pie cup. Fay had a pan. The egg hit an oak and got on his ear. Fay got a bun to mop it up. The ref ate the bun and egg. Pip won the cup. Fay got him a pan as a hat. Pip did lob an egg. It hit the pan, not his ear." },
  { id: "k-190-the-chase-sketch", title: "The chase sketch", pay: 1392, kid: true, text: "Kit ran for Gus in an act. Gus had to put her on a pad in ink. He sat by an oak to do it. Kit sat too. Gus ran for a new go. He sat to do new art. Kit lay by the oak. Gus got her on his pad in a nap. He had a nap act, not a run act." },
  { id: "k-167-the-dust-jig", title: "The dust jig", pay: 1392, kid: true, text: "Ned had a jig at the inn. Pip had a tin peg on his toe. Pip did a jig. Mud got off the rug. Ned had a fan by his eye. Pip did a new jig. Ned got Pip a mop as his cup. Pip put a peg on it. Ned got a tie on the mop and did tug. Pip had a nap to the din." },
  { id: "k-043-the-new-wag", title: "The New Wag", pay: 1392, kid: true, text: "Bo was a wag in a wig. Fay had a cap. Bo put a fig up in the air. It got in her cap. All did cry in joy. Fay sat on a tin by her bed. It did hum. All did cry in joy too. Bo got her cap. Fay got his wig. Now the wag had to sit for the gig." },
  { id: "k-180-the-old-nut-pod", title: "The old nut pod", pay: 1392, kid: true, text: "Ned dug up an old nut pod. Fay put it to her ear. \"So old!\" she did say. Ned put it in a box by a tag. Fay got the tag. It did say ONE NUT. Ned had hid his tea in the pit one day ago. Fay put the pod up in a cup. \"A nut one day old is old!\"" },
  { id: "k-221-the-ice-ray", title: "The ice ray", pay: 1392, kid: true, text: "Ned has an ice ray. He can aim it at Pip. Pip has a cup of tea. Ned let the ray hit it. Now the tea is ice! Kit is by him to eat. She put a fig by the ray. Now it is ice too. Ned had to be the big guy. Now his job is to ice tea." },
  { id: "k-152-the-rowing-ribbon", title: "The rowing ribbon", pay: 1392, kid: true, text: "Bo had to row to a red tie to win. Fay was by the end. Bo got the tie off a peg and in his paw. Bo did row and row. Fay ran by him on the sod. \"You won!\" she did say. Bo did not see her. He got to his den. Now the end was in his tub." },
  { id: "k-192-the-laundry-opera", title: "The laundry opera", pay: 1392, kid: true, text: "Kit had a wet rag on a peg. Pip had to hum a sad act. Kit put the rag by his lip. Pip had a big hum. The air hit the rag. It did bob. Pip did hum for a new go. The rag got dry. Kit put a new rag up. Pip did ask why. \"You can do my wet rag act too.\"" },
  { id: "k-013-the-rod-in-the-jam", title: "The Rod in the Jam", pay: 1392, kid: true, text: "A rod was in jam. Max did say, \"Who can get it may be my son.\" Bo dug in the jar. The rod did not go. Bo set the jar in hot tea. He got the rod out. Max got him a cap. Bo put it on the jar. His law was to let no fly get at the jam." },
  { id: "k-015-the-fox-toll", title: "The Fox Toll", pay: 1392, kid: true, text: "Gus had fur and a red wig. \"I am a fox. Pay me to get by!\" Dot had no gem. She got him a cap. Gus put it on his wig. He did not see. Dot ran by. He put the cap up and saw a nut. Dot put it by him. Gus sat to eat. The fox was not so sly now." },
  { id: "k-044-the-tub-show", title: "The Tub Show", pay: 1416, kid: true, text: "Max sat in a tub. Gus did tug it on a rug. It got in mud and did not go. Max got out to tug. Gus sat in it. The tub did go. Gus was in the big gig now. Max ran in the mud. He put his cap on Gus. Gus now had to tug the tub to his hut." },
  { id: "k-083-the-crowded-ark", title: "The Crowded Ark", pay: 1416, kid: true, text: "Bo let a cat in his ark. The cat had a mat. Bo let a dog in. The dog had a bed. He let a pig in. The pig had a tub. Now Bo did not fit. He put his own mat on the top. \"I can see all of you!\" The pig put its tub on top too. Bo had to fit in the tub." },
  { id: "k-159-the-dessert-vault", title: "The dessert vault", pay: 1416, kid: true, text: "Bo had a pie for a cup. Kit had a key. Bo put the pie in a tin box so no one got to eat it yet. Kit hid the key in the pie. The ref did go to try it. Bo had no key. Kit had no pie. The ref put his cup in a box too. \"Try to get my cup now!\"" },
  { id: "k-196-the-hidden-snack-signal", title: "The hidden snack signal", pay: 1416, kid: true, text: "Pip put jam on a bun to get Bo a spy tag. Gus had to get the bun to Bo. He ate a nut on it. He ate two. At the den, he ate the bun. Bo saw no tag. Gus did go, \"URP!\" Bo put it on a pad. Pip got a tag. It did say to get Bo a new tag to eat." },
  { id: "k-274-the-spy-bow", title: "The spy bow", pay: 1416, kid: true, text: "Fay had to bow to Bo to get a key. She did bow. Bo did bow too. Fay got low. Bo got low too. Her hat hit his hat. The two sat in the mud. Fay got a key off his hat. Bo got her spy tag off her hat. The two had met, but no one had got up yet." },
  { id: "k-140-the-mail-chase", title: "The mail chase", pay: 1416, kid: true, text: "Bo had a tag to get to a pal. Pip put it in a bag and ran. He ran by a log and up an oak. He saw Bo on the tag. Pip ran to Bo. The tag did say to buy a fig. Pip put it in the bag of Bo. Bo did ask Pip to get the bag to his den too." },
  { id: "k-157-the-bread-timer", title: "The bread timer", pay: 1416, kid: true, text: "Ned had a bun in a hot tin. Dot had a toy to go tic. Ned had to get the bun out as it did tic. The toy did go tic. Ned got it out of the sun. He put it in an ice box. Dot did ask why. \"I got the tic toy out,\" he did say. The bun was now tar." },
  { id: "k-191-the-grand-hat-hamper", title: "The grand hat hamper", pay: 1416, kid: true, text: "Dot had to get a fig, a yam and a jam bun. Gus had all in his inn. Dot had no bag. She put her hat on a box. Gus put the fig, yam and bun in it. Dot put the hat on her fur. The jam ran to her ear. Gus got her a rag. She put it on as her new hat." },
  { id: "k-109-the-hot-dish", title: "The hot dish", pay: 1416, kid: true, text: "Bo had a pot too hot to eat. Dot had a fan. Bo did not let her use it. His pot had to be hot to win. The ref got a bit and ran for ice. Bo won a fan. Dot put it by her fan. Bo did not let her use it. He did not eat, but he had a cup and a fan." },
  { id: "k-004-the-small-giant", title: "The Small Giant", pay: 1416, kid: true, text: "Pip put a pea in a pot. It got big. Pip got up to a den in the sky. Max sat on a bed as big as a hut. \"I am a big guy,\" Max did say. Pip saw he was not big at all. He got a box for Max. Max sat in it. Pip got the big bed. Now he had a hut in the sky." },
  { id: "k-170-the-midnight-stakeout", title: "The midnight stakeout", pay: 1416, kid: true, text: "Kit had to spy on a den at eve. Fay had to spy too. Kit got a low din in her ear. She hid by a log. The din got big. Kit got her net. She did lob it at the log. Fay was by it in a big nap. Kit got her up. Fay saw the net. \"Did you get my nap?\"" },
  { id: "k-026-the-owl-post", title: "The Owl Post", pay: 1416, kid: true, text: "Ned had an owl for his job. It had a tag for Pip: tea at six. The owl had a nap. Pip got to Ned at six. \"How did you see my tag?\" Ned did ask. \"We eat at six day by day.\" The owl got up at ten. It ate the tag. Ned had to pay it in pie now." },
  { id: "k-119-the-new-law", title: "The new law", pay: 1416, kid: true, text: "Kit was the law at the inn. \"No mud on the rug!\" he did say. Fay saw mud on his toe. Kit put a paw on the rug to let her see his pin. Fay hit a tin pot. Kit had to rub the rug. He got his pin off. He put it on the mop. Now it was the law." },
  { id: "k-125-the-laser-maze", title: "The laser maze", pay: 1416, kid: true, text: "Pip saw a red tie in a den. Dot had to put it up. Pip had to get a gem on a box. He got low and did pad. The tie hit his ear. A wet rag hit his lip. Dot saw him. \"My rag!\" Pip put the gem on the box. He had to put the rag up. It was his own bib." },
  { id: "k-142-the-lost-cue", title: "The lost cue", pay: 1416, kid: true, text: "Ned had to cry as Gus hit the sod off a log in an act. Gus got on the log. Ned got a mat for him. Gus got off. Ned got him in his paw. The guy who ran the act was mad. He had to do it. Ned did not get him. The guy sat on the mat for a nap." },
  { id: "k-145-the-chase-scene", title: "The chase scene", pay: 1416, kid: true, text: "Dot ran for Fay. Fay had one bun. Dot did hop a log and get low by a van. Fay ran in an inn. Dot ran in too. Fay did nod at the row. Dot had to sit in it. The inn had new pie. Dot got two. Fay did ask for one. Dot ran off. Fay had to run now." },
  { id: "k-187-the-spy-beard", title: "The spy beard", pay: 1416, kid: true, text: "Fay had a big wig to spy on Pip. Pip saw tan fur by the gap. He did not see Fay. He got a tub and did tug her wig. Fay got in by the wig. Pip put gel on it. Fay had to get it off. Pip got his mop. \"It has a pal now!\" Fay put it on the mop." },
  { id: "k-001-the-pea-test", title: "The Pea Test", pay: 1416, kid: true, text: "A pea was in her bed. Dot lay on a rug. Gus ate in his den. Dot did not nap. She did not see a pea. \"Is a rat in my bed?\" Gus got his tin. He put it by her ear. Dot sat up. \"Oh, it is you!\" Dot put a cap on his tin. Gus did not eat. Dot had her nap." },
  { id: "k-201-the-sun-tax", title: "The sun tax", pay: 1416, kid: true, text: "Pip met Bo on a red orb. Bo had a tin hat and a tax jar. \"Pay me for the sun,\" he bid. Pip put a pea in the jar. Bo got mad. \"I am the big guy!\" Pip put the jar on his hat. The pea hit his lip. Bo had to bow to get it. Pip got the sun at no fee." },
  { id: "k-206-the-egg-orb", title: "The egg orb", pay: 1416, kid: true, text: "Dot and Pip got a toy jet to a big egg. Dot set a pin on it. The pin cut a gap. A goo ran out. \"It has a sea!\" Pip did say. Dot put a cup at the gap. Gus ran by, a pan on his arm. It was his egg. Dot put the cup in his paw. The new sea was an egg for tea." },
  { id: "k-175-the-safe-delivery", title: "The safe delivery", pay: 1440, kid: true, text: "Kit did not get a box lid off. Pip had a van. The two got the box in it. At a hut, a guy got up. \"My box!\" he did say. He got Kit a nut. Pip did ask to see in it. The guy got the lid off. It had a box in it too. Pip had to get the new box to a new hut." },
  { id: "k-085-the-court-picnic", title: "The Court Picnic", pay: 1440, kid: true, text: "Gus had a den in an oak. Bo got him to a big den for tea. Max hit a pot. All had to bow. Gus sat to eat. Max hit the pot. All had to bow. Gus got his fig and ran to his oak. Bo ran too. Max hit his pot. No one did bow. Max ran to the oak for tea." },
  { id: "k-058-the-name-tag", title: "The Name Tag", pay: 1440, kid: true, text: "A sly imp had a gem. Fay had to say who he was to get it. She did try Kit. The imp did say no. She did try Max. The imp did say no. He did bow. His hat got off. It had Gus on it in ink. Fay did say Gus. She got the gem. Gus hid his hat in a bag." },
  { id: "k-077-the-twin-mop", title: "The Twin Mop", pay: 1440, kid: true, text: "Kit had to mop a den. She did say a hex. A new Kit was by her. \"Mop for me.\" \"No, mop for me.\" Kit and Kit sat. Dot put a mop by one and a mop by one. Now Kit and Kit had to mop. Kit had a pal, but no nap. Dot put a tag on the new Kit so she saw who was who." },
  { id: "k-144-the-hero-cape", title: "The hero cape", pay: 1440, kid: true, text: "Pip had a big rag to fly in. Kit did cry for aid in an icy den. Pip got off a box. His rag got on a peg. Kit got him off. Pip got her the rag to use in the den. Kit got him a fig. Pip ran to his den. He was so icy he had to ask Kit for his rag." },
  { id: "k-038-the-flying-hut", title: "The Flying Hut", pay: 1440, kid: true, text: "Kit saw fog by her hut. \"Our hut can fly!\" Fay got a cup to get dew in the sky. Kit put a net out to get fog. No fog got in it. The fog did go. The hut was in its oak. Fay put tea in the cup. Kit put a bun in the net. \"We got sky tea!\" Fay did say." },
  { id: "k-155-the-tug-trophy", title: "The tug trophy", pay: 1440, kid: true, text: "Kit and Bo had to tug a tie. A cup was by the end. Kit got low. Bo got low. Fay saw a fig on the tie. \"Let go!\" she did say. Kit let go. Bo let go. Fay got the fig. The tie lay on the sod. Kit put the cup by it. The tie had won by no act at all." },
  { id: "k-035-the-tea-war", title: "The Tea War", pay: 1440, kid: true, text: "Gus had a tin for his job. Max had a cup. Gus did say his tin was to bar a foe. A bee got in the tea. Max put his cup on it. Gus put his tin on the pot. Now no bee got in. His tin had won a war. Max got the bee a bit of jam so it did not go to war." },
  { id: "k-148-the-tiny-spy", title: "The tiny spy", pay: 1440, kid: true, text: "Fay put on a wig to spy on Ned. Ned had a fig bag. He put it in her lap. Fay had to get the wig up to see. Ned got to his den. Fay let all get a fig for a nut. Ned got to the wig. \"Did Fay go by?\" he did ask. Fay had the nut bag. \"No,\" she did say." },
  { id: "k-153-the-golf-caddy", title: "The golf caddy", pay: 1440, kid: true, text: "Dot hit an orb to a pit. Gus had to get it for her. He got it out of the pit. Dot hit it for a new go. Gus got it for a new go. Dot did ask Gus to sit. Gus put the orb in a cup by her. \"Now it is in a pit by a paw,\" he did say. Dot let him win." },
  { id: "k-179-the-vine-tax", title: "The vine tax", pay: 1440, kid: true, text: "Pip had to get by a gap. Kit had a tie for him. Pip had a tie for Kit. The two sat. One had to tug as one got on the tie. Pip put his end on an oak. Kit got by the gap. She put her end on it too. The oak got a nut as its fee. It did not use it." },
  { id: "k-128-the-rare-bloom", title: "The rare bloom", pay: 1440, kid: true, text: "Fay had to get a red bud. Pip had a map. The two saw red by a log. It did bob. Pip hid. Fay ran up. It was Dot in a hat. Dot let Fay get the red bow. Fay put it on the map in ink. Pip did say he had to get a bud yet. Dot put the bow on a rod. \"Try now.\"" },
  { id: "k-009-the-rescue-net", title: "The Rescue Net", pay: 1440, kid: true, text: "Dot sat in a den up in an oak. Kit was on the sod. Dot let a net go. Kit got in it. Dot did tug him up. Kit had jam. Dot ate it. Kit saw a gap by a rug. A log led out of it to the sod. Kit got to the sod by it. Dot had the net for her jam pot." },
  { id: "k-076-the-brave-fly-saver", title: "The Brave Fly Saver", pay: 1440, kid: true, text: "Bo had to sew a cap. A fly sat in his jam. Bo got a rod to get it out. He put it on a rag. It did not fly. Bo got a fan. It did fly. Max saw a tag on Bo: I won. Max let Bo sit by his gap. Bo put jam by it. A fly was in his new den. \"I may win all day!\"" },
  { id: "k-162-the-treasure-plug", title: "The treasure plug", pay: 1464, kid: true, text: "Kit had a gem in a box. Fay had a sea tub. A gap in the tub let sea in. Kit put the gem in the gap. The tub was dry. Fay had to buy a bun at the bay. Kit got the gem out to pay. The tub got wet. Fay put it in the gap. \"The sea can get a gem. We get no bun.\"" },
  { id: "k-205-the-hat-bot", title: "The hat bot", pay: 1464, kid: true, text: "Bo has a bot to tip his hat. Kit is in his hut to see it. \"Tip!\" The bot can hit the hat. It is in a tub now. Bo has a new hat. \"Tip!\" It is in the tub too. Kit has a cup of tea for the bot. \"Tip!\" The tea is in a hat. Bo has tea to sip but no dry hat." },
  { id: "k-158-the-pea-tea-mix", title: "The pea tea mix", pay: 1464, kid: true, text: "Pip had a pea pot. Max had a tea pot. Pip put oil in the tea. Max put jam in the pea pot. The ref saw the two. Pip and Max put it all in a big pot. The ref had a sip. \"Odd,\" he did say. The two ate it all. The ref saw a dry pot. \"Top job!\" The ref let the two win." },
  { id: "k-020-the-sleep-race", title: "The Sleep Race", pay: 1464, kid: true, text: "Dot and Ned ran to a bed up in an oak. Dot ran. Ned ate a fig. Dot got to the bed and had a nap. Ned got up to her. Dot had all the bed. Ned did say he won, for he did not nap yet. Dot did not get up. Ned had a nap in his cup. He won a bed of his own." },
  { id: "k-094-the-royal-act", title: "The Royal Act", pay: 1464, kid: true, text: "Max had one job for an act. Ned did hum. Bo did a jig. Max had to pay for one. He put Ned and Bo on one rug. Ned did hum as Bo did a jig. Now it was one act. Max put a nut on the rug for pay. Ned ate a bit. Bo ate a bit. Max did a jig too. He got no nut." },
  { id: "k-200-the-epic-bedtime", title: "The epic bedtime", pay: 1464, kid: true, text: "Dot had to put Pip to bed. Pip did ask for an ode. Dot did say one. Pip did ask for a hum. Dot did hum one. Pip did ask for a cup of tea. Dot got one. Pip did ask for a new ode. Dot sat by his bed. She had a nap. Pip put a rug on her. He did not get his ode." },
  { id: "k-193-the-fig-trial", title: "The fig trial", pay: 1464, kid: true, text: "Bo did say Max had got his fig. Fay was the law. She put the fig in a pot. Bo did tap the pot. Max did tap it too. Fay had a bit to see who had it. She had a new bit. No fig was in the pot. \"You can go,\" Fay did say. Bo and Max did ask who ate the fig." },
  { id: "k-299-the-sleep-switch", title: "The sleep switch", pay: 1464, kid: true, text: "Ned had a ray to get Bo to nap. Bo lay on a cot. He had a nap. Ned hit the ray. Bo did not go. Ned hit it a lot. Bo did not go. Ned put his ear by Bo. Bo had a nap. Ned sat. He had a nap too. Bo got up and put a rug on him. The ray had won a nap for Ned." },
  { id: "k-112-the-sea-hat", title: "The sea hat", pay: 1464, kid: true, text: "Bo had a hat to use at sea. Fay had a sea tub. Bo put his hat on and got in. The air got his hat off. Fay got it on a rod. Bo did bow to the hat. \"The hat is now the big guy,\" he did say. Fay got the hat off the rod. She sat on it. \"Now I am on top.\"" },
  { id: "k-002-the-ice-hat", title: "The Ice Hat", pay: 1464, kid: true, text: "Kit had an ice hat. Bo had a hay hat. Kit got a wet ear. Bo got an ant in his fur. At a big hop, all had to do a jig. Kit put her hat in a tub. Bo put his hat in too. The hay got wet. The ice was not a hat now. Kit and Bo did a jig. No hat got in the way." },
  { id: "k-006-the-red-hat", title: "The Red Hat", pay: 1464, kid: true, text: "Kit had a red hat and a big bag. In it was pie, jam, a cup, and a rug. Gus was to get the bag. Kit did not get it up. Gus ran to her. He ate pie. Kit ate jam. Kit and Gus lay on the rug for a nap. Kit got the bag up now. Gus got it. \"I got a cup and a nap. Oh, my!\"" },
  { id: "k-101-the-big-cup", title: "The big cup", pay: 1464, kid: true, text: "Pip had to get the cup. Kit had to hit a red orb. Pip saw a fig by the net. He ran for it. Kit hit the orb. It hit the paw of Pip and got in the net. The ref let Pip win. Pip put his fig in the cup. Kit did not get a cup. He got a wet rag to rub it." },
  { id: "k-169-the-sheriff-badge-swap", title: "The sheriff badge swap", pay: 1464, kid: true, text: "Bo had a pin as the law of the inn. Max had a bad toe. Bo got him the pin to use. Max put it on his fur. \"No run!\" he did say. Bo had to hop. Max sat. \"No hop!\" Bo sat too. The two sat to eve. Bo did ask for his pin. Max did say the law had to nap." },
  { id: "k-130-the-great-peak", title: "The great peak", pay: 1464, kid: true, text: "Dot and Gus got up a big top. Dot put a tie on a rod. Gus put up a rag. The big top was the top of a van. The van did go. The cab man got the two to the den. Dot put one nut in his paw. Gus ate his fig. \"I was at the top,\" he did say. \"Now I can sit in the van.\"" },
  { id: "k-160-the-sad-cook-act", title: "The sad cook act", pay: 1464, kid: true, text: "Gus had to cut a yam. Fay sat by him. The yam hit his toe. He did cry. Fay put a mat by him. \"Sit and say why you cry,\" she did say. Gus put the yam up. Fay did cry too. The ref saw the two. He got all a cup for the sad act. Gus did not cut any yam for tea." },
  { id: "k-204-the-spy-nap", title: "The spy nap", pay: 1464, kid: true, text: "Fay had to get by Max to get a map. She put on a wig and lay in a cot. Max saw the wig and set a rug on her. \"She can nap,\" he did say. Fay lay as if she was in a nap. At six, Max got her up for tea. The map was on a tin lid. Fay got it. She got a nap too." },
  { id: "k-296-the-spy-ray", title: "The spy ray", pay: 1488, kid: true, text: "Fay had to get by a red ray. Gus had a box to get it low. Fay got low. The ray got low too. Fay got too low to get up. Gus got it low too. Fay lay on a mat. The ray did too. Fay sat up. \"You try!\" Gus got low. Fay hit the red dot on his box. She got by Gus." },
  { id: "k-082-the-last-hot-dog", title: "The Last Hot Dog", pay: 1488, kid: true, text: "Fay let Pip use a hex. He did ask for a hot dog. A hot dog was by him. Bo did ask for one on Pip. Now Pip had a hot dog on his lip. Pip did ask for no hot dog. It was not on his lip now. Bo had no hot dog. Pip had no hot dog. Fay had a hot dog of her own." },
  { id: "k-072-the-covered-law", title: "The Covered Law", pay: 1488, kid: true, text: "Max had a law on a tag: No pie. Dot put a pie on the tag. It hid the No. Max saw pie. He ate it. Now he saw No pie. Dot saw no pie too. She got him a new tag: No tax. Max put pie on it at six. Dot ate the pie. Now she saw No tax. She put a nut in her bag." },
  { id: "k-011-the-seven-seats", title: "The Seven Seats", pay: 1488, kid: true, text: "Fay saw a hut. Dot and her kin sat in it. Dot had a cup for Fay. Fay sat on a pot. It did hum. She sat on a box. It had jam in it. She sat on a log. Dot and her kin sat on it too. Fay got up and sat on a mat. Now the log had no gap, but Fay had all the mat." },
  { id: "k-093-the-sitting-hex", title: "The Sitting Hex", pay: 1488, kid: true, text: "Max had a hex on his eye. If he saw you, you had to sit. Pip hid by a big tin. He put it up. Max saw his own eye in it. He had to sit. Pip ran by him. Max put a rag on his eye. Now no one had to sit. Pip let Max put a paw on him. Max got to his den." },
  { id: "k-071-the-forbidden-pot", title: "The Forbidden Pot", pay: 1488, kid: true, text: "Bo had a pot. \"Do not get its lid up.\" Kit did not get its lid up. She sat by it. The pot did mew. Bo ran in. \"Did you see my cat?\" \"No. It did mew.\" Bo got the lid up. The cat got out. Kit put the lid on his top. \"Mew for me!\" Bo did mew. The cat had a nap." },
  { id: "k-165-the-sea-lid-jaw", title: "The sea lid jaw", pay: 1488, kid: true, text: "Dot saw a big jaw in the sea. Bo hid in the tub. Dot got a rod to jab it. It did bob. Bo did cry. Dot got it up. It was a pan lid. Bo had put it out by the sea. Dot got it to him. Bo put it on his pot. Now the sea guy had to sit on a pot of tea." },
  { id: "k-091-the-just-right-pot", title: "The Just-Right Pot", pay: 1512, kid: true, text: "Bo saw a cup of hot tea. He did not sip. He saw a cup of ice tea. He did not sip. He saw a pot. He put the hot tea and ice tea in it. Kit, Pip, and Dot ran in. Bo had tea for all. The pot was not hot and not ice. Bo had no cup now. He had to use the lid." },
  { id: "k-060-the-vanishing-grade", title: "The Vanishing Grade", pay: 1512, kid: true, text: "Fay had a pen. No one saw its ink. She put an A on a tag for Kit. Kit did not see it. Bo saw no ink. Kit did say she had an A. Bo did say he had an A too. Fay got a new pen. It had red ink. Kit and Bo had a new try. Now Bo had a B. Kit had a C. Bo did ask for the old pen." },
  { id: "k-147-the-time-clock", title: "The time clock", pay: 1512, kid: true, text: "Kit had a toy to go to an old day. He hit a peg. Bo saw him. \"We can eat pie now,\" Bo did say. Kit saw his pie. He had to get it hot. He hit the peg for a new go. Bo saw him. \"We can eat pie now.\" Kit hid the toy. He ate the pie as it was to end the day." },
  { id: "k-136-the-royal-bath", title: "The royal bath", pay: 1512, kid: true, text: "Pip had a hat for his dip. Gus had a tub. Pip sat in it. Gus put hot tea in it. The hat hid the eye of Pip. Gus got it off. Pip put it on a toy. Gus did bow to the toy. \"Sir, you can go in.\" Pip had to get out of the tub to bow too. The toy got the dry mat." },
  { id: "k-088-the-tall-band", title: "The Tall Band", pay: 1512, kid: true, text: "Bo had a hut for a gig. He did not let Pip, Kit, Gus, and Dot in. Pip sat on Kit. Kit sat on Gus. Dot sat on Pip. All did hum. Bo saw a big mob. He ran out. The mob got in. Pip put a rug by Bo. \"We can hum for you.\" Bo ran in. He sat on top. He had to hum too." },
  { id: "k-199-the-secret-handshake", title: "The secret handshake", pay: 1512, kid: true, text: "Kit had a spy tap to get Ned. She had to tap his paw and do one new tap. Ned had a paw out. Kit did tap it. Ned did tap her paw. Kit did tap his for a new go. Ned did too. The two did tap all day. Bo had tea. He did ask why. Kit had to see if Ned was a pal yet." },
  { id: "k-039-the-cow-cap", title: "The Cow Cap", pay: 1512, kid: true, text: "Max hid a cap. Its new pal was to get his job. Bo saw it on a cow. He let the cow eat hay. Its cap got on the sod. Bo got it. He let Max use it. \"Why not you?\" Max did ask. \"The cow ate hay in his cap. I may eat hay for my job.\" Max hid the cap in his pie tin." },
  { id: "k-005-the-bog-costume", title: "The Bog Costume", pay: 1512, kid: true, text: "Bo sat by a bog in a red cap. \"I am an eel.\" Dot did ask him to dip in. Bo did dip. His cap got wet. \"I am not an eel!\" Dot got his cap out. She put a pea in it. The cap sat on the bog. The pea had a tub now. Bo had no cap. Dot let him use her dry rag. It fit him." },
  { id: "k-105-the-grand-kick", title: "The grand kick", pay: 1536, kid: true, text: "Pip had to hit an orb to win. Bo was in the net. Bo saw jam on the orb. He got a wet rag to rub it. Pip sat on the sod. Bo got the jam off. The ref got Bo a bib. Pip hit the orb. It got in the net. Bo got jam on the bib. It was on his paw all the day." },
  { id: "k-134-the-silent-round", title: "The silent round", pay: 1536, kid: true, text: "Gus had to sit on a log to win a fig. Ned had to be mum. A fly sat on the lip of Gus. Gus did fan it off. The fly sat on Ned. Ned did go, \"Ah!\" Gus won the fig. The fly sat on it. Gus did not eat as the fly was on it. Ned got it off. He ate the fig for Gus." },
  { id: "k-065-the-pet-test", title: "The Pet Test", pay: 1536, kid: true, text: "Kit had to get a pet for Bo to see. Her pet rat hid in a bag. Bo saw no rat. Kit put a pea by the bag. The pea was not by the bag now. Bo saw no rat. Kit put jam by the bag. The rat ran out. It had jam on its jaw. Bo put an A in the bag. The rat ate it too." },
  { id: "k-100-the-early-end", title: "The Early End", pay: 1536, kid: true, text: "Kit had a hex for end. She put it on a tag. Bo had to dig. Kit put the tag by him. He sat. Ned had to sew. Kit put the tag by him. He sat. Kit had to eat. Kit put the tag by her pie. She did not get a bit. \"Not yet!\" She cut the tag up. All got up. Kit got her pie." },
  { id: "k-003-the-long-nap", title: "The Long Nap", pay: 1536, kid: true, text: "Fay had to nap for an age. Ned had to end her hex. He hit a tin. Fay did not get up. He hit a pan. Fay did not get up. Ned set a pie by her lip. Fay sat up and ate. \"Is the hex at an end?\" Ned did ask. Fay ate a bit. \"Yes. But I may nap for an age if you get me a pie.\"" },
  { id: "k-150-the-grand-nap", title: "The grand nap", pay: 1536, kid: true, text: "Pip saw a toy go tic. Max lay on a mat. \"The end of all is by us!\" Pip did say. He hid a fig and had Max in his lap. The toy did go TIC. Max got up and did ask for tea. Pip got his box out. \"Max can nap!\" he did say. Max got on the mat. \"So let me nap to the end.\"" },
  { id: "k-036-the-hop-hat", title: "The Hop Hat", pay: 1560, kid: true, text: "Bo had a hex on his hat. It let him go far in a hop. Ned set a fig on a mat. Bo did hop to it. His hat got off. Bo had to hop to his hat. Now he was by the fig. Ned put the hat on the fig. It did not hop. Bo had to put it on to get the hex. He ate the fig." },
  { id: "k-025-the-hat-hut", title: "The Hat Hut", pay: 1560, kid: true, text: "Dot had a big hat. No one was to see her in it. Kit saw a paw. Dot hid it. Kit saw an ear. Dot hid it. Kit saw a dot. \"Is it a bed?\" He sat. Dot did cry. Kit got up. Dot got her hat off. Kit put it on a peg. It was a hut now. Dot put jam in it. Kit did not sit on the jam." },
  { id: "k-115-the-pond-chase", title: "The pond chase", pay: 1560, kid: true, text: "Gus saw Kit row off in a sea tub. Kit had his box. Gus ran to get a tub too. He got to Kit by eve. \"My box!\" he did say. Kit put it in his lap. It had a bun for Gus and a bun for Kit. Gus ate his bun. Kit ate her bun. \"Do we row now?\" Gus did ask. Kit put on her nap cap." },
  { id: "k-010-the-pie-trail", title: "The Pie Trail", pay: 1560, kid: true, text: "Gus and Bo put pie by a log and by an oak. A jay ate the pie. Bo did not see how to go. Gus fed the jay a nut. It led him to an oak. Gus and Bo had a hut up in it. Bo put the jay on a map in ink. Gus put a nut by its lip. \"We can pay our pal.\" No jay ate the map." },
  { id: "k-032-the-tin-rim", title: "The Tin Rim", pay: 1560, kid: true, text: "Dot got a rim of tin. Bo did say it got him to ask for pie. Dot put it on her paw. She did not ask for pie. Bo had jam on his lip. \"You ate pie. You did not see my rim yet!\" Dot put a rag in it. Bo ate pie. Dot had a dry lap. Bo had pie. The rim had no hex at all." },
  { id: "k-056-the-bog-hero", title: "The Bog Hero", pay: 1584, kid: true, text: "Ned had to get tea on the far end of a bog. He did not opt to get wet. He put a log by the bog. It did not get to the far end. He put a net on it. It did not get to the far end. Bo had a new pot of tea. He put it by Ned. Ned sat to sip. Bo put pie in the net." },
  { id: "k-019-the-mud-pig", title: "The Mud Pig", pay: 1584, kid: true, text: "Fay got mud on her fur. Bo saw her in a tub. \"A pig is in our den!\" Fay did nod. Bo got the pig a pea. Fay did not eat it. She got a rag and the mud was off. Bo saw Fay. He got her a fig. Fay ate it. Fay put mud on her fur. \"The pig may ask for pie!\" Bo got the rag, not the pie." },
  { id: "k-049-the-tea-pin", title: "The Tea Pin", pay: 1584, kid: true, text: "Ned had a pin to be his map. It did aim at a rod. Bo had it in his paw. Bo ran to a cot. Ned ran too. Bo ran to an oak. Ned ran too. Bo sat. Ned sat. Bo put the rod by a cup. Ned had tea. His pin had got him to tea at six. He had to get a map for the way to his hut." },
  { id: "k-108-the-cake-bed", title: "The cake bed", pay: 1584, kid: true, text: "Max had a pie as big as a bed. Ned had one as big as his paw. Max had to cut his pie for the ref. The saw got in it and did not get out. Ned got the ref his pie. Ned won. Max put a rug on his pie and had a nap. As he got up, the saw was yet in it. It had its own rug." },
  { id: "k-017-the-jug-gifts", title: "The Jug Gifts", pay: 1608, kid: true, text: "Kit was in a jug. Max got her out. \"Ask me for a toy.\" Max did ask for a car. Kit got a jar. Max did ask for a gem. Kit got jam. Max did ask for pie. Kit got pie. Max ate. Kit ate too. Max put jam in his jar. He got no car and no gem, but his jar had jam. Kit got no jug, but she got pie." },
  { id: "k-012-the-egg-quest", title: "The Egg Quest", pay: 1608, kid: true, text: "Pip had a map. Ned had a tin to hit. Pip led Ned by a log to a hen. It had an egg. Pip got it. Ned hit his tin. The hen sat in the tin. Pip saw an egg in it. Pip got an egg and Ned got an egg. Ned did not get his tin. He had to use a pot. The hen had a new bed. Pip had his tea." },
  { id: "k-278-the-tin-wig", title: "The tin wig", pay: 1608, kid: true, text: "Max got Bo a tin wig. It had a red gem in it. The gem can get tin to hug it. Bo put it on to be an old guy. A tin rod got on it. A tin pin got on it too. Bo ran to the tea hut. A cup got on his wig. Max got the wig off. Bo had no wig, but he had to rub the tea set." },
  { id: "k-021-the-red-touch", title: "The Red Touch", pay: 1632, kid: true, text: "Max put his paw in red dye. He was Sir Max for a day. All he got was red. His cup was red. His hat was red. He got a fig. The fig was red too. Max did not eat it. Fay got a rag and a tub. Max put his paw in it. Now he ate a new fig. Fay put his red hat on the tub. It was Sir Tub now." },
  { id: "k-041-the-bug-portrait", title: "The Bug Portrait", pay: 1632, kid: true, text: "Ned sat for Dot to do his art. A bug sat on his ear. He hit it. Dot put an arm up in the air in her art. The bug ran to his jaw. He hit it. Dot put an arm by his jaw too. Ned saw a lot of him in the art. \"Now I can hit a bug and a bug!\" Dot put a bug by one arm and by one arm." },
  { id: "k-194-the-mop-in-the-mud", title: "The mop in the mud", pay: 1656, kid: true, text: "Ned got a rod in mud. Gus did say the guy who got it out was to be the law. Ned did tug. Gus did tug. The two hit the sod. Dot had a tub of tea. She put tea in the mud. The mud got wet. Dot got the rod out. It was a mop. Gus did bow to Dot. Dot got him the mop. \"The law has a rug job now.\"" },
  { id: "k-022-the-lunch-hat", title: "The Lunch Hat", pay: 1680, kid: true, text: "Pip had to put Kit and Bo in a row. He did use a hat. Kit put it on. It did say, \"Nut!\" Kit sat by a nut. Bo put it on. It did say, \"Fig!\" Bo sat by a fig. Pip saw a jay in it. It had a nut and a fig. Kit fed the jay. Bo ate the fig. All got a row now. It was a row for tea. Pip got a cap for the jay." },
  { id: "k-096-the-pen-zoo", title: "The Pen Zoo", pay: 1680, kid: true, text: "Kit had a pen for a hex. She put \"fig\" on a tag in ink. A fig was on her mat. She put \"pie\" on it. A pie was on her mat. She put \"cat\" on it. A cat was on her mat. It ate the pie. Kit put \"dog\" on it. A dog was on her mat too. Bo got the pen out of her paw. Kit had to get tea for a cat and a dog now." },
  { id: "k-034-the-hat-riddle", title: "The Laugh Toll", pay: 1680, kid: true, text: "Fay sat by a gap. Kit had to get her to cry in joy to go by. He put a fig on his lip. Fay did not cry in joy. He put it on his ear. She did not cry in joy. A bee sat on it. Kit got up and ran. The fig got in her cap. Fay did cry in joy. Kit ran by. The bee had no fee to pay." },
  { id: "k-197-the-wax-villain", title: "The wax villain", pay: 1680, kid: true, text: "Max put wax in his fur to be the bad guy. Dot had to run for an act. Max got a paw up. It was in the wax. Dot got oil and a rag. Max did say she had to run. Dot got the wax out. Max got his paw up at her. Dot put the rag on the sod. Dot had run off. His big bad arm was up at a rag." },
  { id: "k-007-the-three-huts", title: "The Three Huts", pay: 1680, kid: true, text: "Ned had a hay hut. Fay had a log hut. Bo had a tin hut. Gus had a big fan. He let it run by the hay hut. The hut had a dip. He let it run by the log hut. A log hit the sod. The tin hut did hum. All sat in it. Gus set his fan to low. Now the hut was not hot. Ned put hay in it for a bed of hay." },
  { id: "k-104-the-slow-race", title: "The slow race", pay: 1680, kid: true, text: "Fay had a car. Ned had a van. One peg on his van was bad. Fay ran off to win. Ned got a new peg and put it in. Fay had no way to end her run. She hit the hay at the end. Ned won. He got Fay out of the hay. She had a nap in it as he got to his den. She did not get up to get her car." },
  { id: "k-014-the-round-rug", title: "The Round Rug", pay: 1704, kid: true, text: "Kit had a rug for her kin. All had to sit on it. Bo did not get a bit of rug. Kit put a fig in the pot by her bed. All ran to the pot. Bo had all the rug now. Kit cut the fig up. Bo got a bit too. He sat on the rug to eat it. The kin sat by him, not on the rug. Bo had all the rug now." }
);
